const questionBanks = {
easyBoss:[
// --- EFFICIENCY ---
{ id:2000,q:"The Architect speaks: 'No market stands alone. Balance them all.' What condition defines allocative efficiency across markets?",options:["P = ATC in all markets","P = MC in all markets","MR = MC for monopolists","Demand equals supply"],a:1,tag:"efficiency",type:"definition",objective:"LO11.2",feedback:"Allocative efficiency requires P = MC—value equals cost."},
{ id:2001,q:"The Architect presses: 'Check the alignment.' If P = MC in a market, what does this imply?",options:["Maximum profit","Allocative efficiency","Zero cost","Demand collapse"],a:1,tag:"efficiency",type:"interpretation",objective:"LO11.2",feedback:"When P = MC, value equals cost—efficient allocation."},
{ id:2002,q:"The Architect destabilizes the grid: 'Restore balance.' In a market, P = 18 while MC = 12. What must occur to reach efficiency?",options:["Reduce output","Increase output","Do nothing","Raise fixed costs"],a:1,tag:"efficiency",type:"interpretation",objective:"LO11.2",feedback:"P > MC → underproduction. Increase output."},
// --- INTERACTION ---
{ id:2003,q:"The Architect declares: 'No market stands alone.' What does interaction between markets mean?",options:["Markets operate independently","Changes in one market affect others","Only prices matter","Only quantity matters"],a:1,tag:"interaction",type:"definition",objective:"LO11.1",feedback:"Markets are interconnected—shocks spill across them."},
{ id:2004,q:"The Architect adjusts the system: 'Trace the connection.' Demand for steel rises, increasing its price. Steel is an input for cars. What happens in the car market?",options:["Car demand rises directly","Car supply shifts left","Car supply shifts right","No effect"],a:1,tag:"interaction",type:"interpretation",objective:"LO11.1",feedback:"Higher input prices raise costs → supply shifts left."},
{ id:2005,q:"The Architect observes: 'Markets echo each other.' A tax is placed on electricity production. What is the most immediate effect?",options:["Demand for electricity increases","Supply of electricity decreases","Supply of electricity increases","No change occurs"],a:1,tag:"interaction",type:"interpretation",objective:"LO11.1",feedback:"Taxes increase costs → supply shifts left."},
// --- FAILURE ---
{ id:2006,q:"The Architect warns: 'The system is breaking.' Pollution from production imposes costs on others not involved in the market. What is this called?",options:["Market power","Externality","Public good","Efficiency"],a:1,tag:"failure",type:"definition",objective:"LO11.3",feedback:"Externalities are costs or benefits imposed on third parties."},
{ id:2007,q:"The Architect continues: 'What is the consequence?' Negative externalities cause markets to...",options:["Produce efficiently","Overproduce","Underproduce","Reach equilibrium"],a:1,tag:"failure",type:"interpretation",objective:"LO11.3",feedback:"External costs are ignored → overproduction."},
{ id:2008,q:"The Architect challenges: 'Correct the failure.' If a market produces too much due to negative externalities, what is the efficient response?",options:["Increase production","Tax the activity","Subsidize consumers","Do nothing"],a:1,tag:"failure",type:"interpretation",objective:"LO11.3",feedback:"Taxes reduce overproduction and move toward efficiency."},
// --- POWER ---
{ id:2009,q:"The Architect states: 'Power shifts outcomes.' What is market power?",options:["Ability to control costs","Ability to influence price","Ability to eliminate demand","Ability to reduce supply"],a:1,tag:"power",type:"definition",objective:"LO12.1",feedback:"Market power means influencing price."},
{ id:2010,q:"The Architect tightens control: 'One firm dominates.' A monopolist produces where MR = MC. Compared to a competitive market, what is true?",options:["Price is lower","Output is higher","Price is higher","Efficiency is achieved"],a:2,tag:"power",type:"interpretation",objective:"LO12.2",feedback:"Monopolies restrict output → higher prices."},
{ id:2011,q:"The Architect presses: 'Power has consequences.' Why does monopoly create deadweight loss?",options:["It produces too much output","It produces too little output","It sets price equal to MC","It increases consumer surplus"],a:1,tag:"power",type:"interpretation",objective:"LO12.3",feedback:"Underproduction means lost gains from trade."},
// --- STRATEGY ---
{ id:2012,q:"The Architect whispers: 'Anticipate others.' In oligopoly, firms must consider what when making decisions?",options:["Only their own costs","Government policy only","Reactions of other firms","Random outcomes"],a:2,tag:"strategy",type:"definition",objective:"LO13.1",feedback:"Strategic interdependence defines oligopoly."},
{ id:2013,q:"The Architect presses: 'Think carefully.' Why must firms anticipate rivals in oligopoly?",options:["To reduce costs","Because outcomes depend on reactions","To eliminate demand","Because prices are fixed"],a:1,tag:"strategy",type:"interpretation",objective:"LO13.1",feedback:"Decisions depend on how others respond."},
{ id:2014,q:"The Architect tests you: 'Think ahead.' If two firms compete and each ignores the other's response, what is likely?",options:["Efficient outcome","Cooperative equilibrium","Strategic mistake","Perfect competition"],a:2,tag:"strategy",type:"interpretation",objective:"LO13.1",feedback:"Ignoring reactions leads to poor strategic decisions."},
// --- EQUITY ---
{ id:2015,q:"The Architect reflects: 'Efficiency is not fairness.' What does equity concern?",options:["Total surplus","Fair distribution of outcomes","Marginal cost pricing","Market equilibrium"],a:1,tag:"equity",type:"definition",objective:"LO11.5",feedback:"Equity focuses on fairness, not efficiency."},
{ id:2016,q:"The Architect challenges: 'Balance the system.' Why might a policy reduce efficiency but improve equity?",options:["It lowers costs","It redistributes outcomes","It increases supply","It eliminates demand"],a:1,tag:"equity",type:"interpretation",objective:"LO11.5",feedback:"Redistribution can create efficiency tradeoffs."},
{ id:2017,q:"The Architect challenges: 'Choose your priority.' A policy increases total surplus but worsens inequality. What is the trade-off?",options:["Efficiency vs. cost","Equity vs. efficiency","Supply vs. demand","Short run vs. long run"],a:1,tag:"equity",type:"interpretation",objective:"LO11.5",feedback:"Policies often trade off fairness and efficiency."}
],

mediumBoss:[

// --- POWER ---
{ id:3000,q:"The Price Maker smirks: 'I do not take prices—I set them.' What rule determines a monopolist’s output?",options:["P = MC","MR = MC","ATC minimized","Demand maximized"],a:1,tag:"power",type:"definition",objective:"LO12.2",feedback:"A monopolist chooses output where MR = MC, then charges the price consumers will pay on the demand curve."},
{ id:3001,q:"The Price Maker presses: 'Follow the logic.' If a monopolist sets output where MR = MC, why is price above MC?",options:["Costs are higher","Demand curve lies above MR","Firms want efficiency","Supply is fixed"],a:1,tag:"power",type:"interpretation",objective:"LO12.2",feedback:"With a downward-sloping demand curve, marginal revenue lies below price, so the monopoly price exceeds marginal cost."},
{ id:3002,q:"The Price Maker tightens control: 'Exploit the weak.' A firm identifies two groups with different elasticities. What is the optimal strategy?",options:["Charge the same price to both","Charge higher prices to more elastic demand","Charge higher prices to less elastic demand","Reduce output equally"],a:2,tag:"power",type:"interpretation",objective:"LO12.4",feedback:"The firm charges a higher markup to the group with less elastic demand."},

// --- EFFICIENCY ---
{ id:3003,q:"The Price Maker scoffs: 'Efficiency is not my concern.' What defines allocative efficiency?",options:["P = ATC","P = MC","MR = MC","Profit maximized"],a:1,tag:"efficiency",type:"definition",objective:"LO11.2",feedback:"Allocative efficiency occurs when price equals marginal cost."},
{ id:3004,q:"The Price Maker explains: 'Observe the distortion.' When monopoly sets P > MC, what happens to output?",options:["Output increases","Output decreases below efficient level","Output stays the same","Output becomes efficient"],a:1,tag:"efficiency",type:"interpretation",objective:"LO12.3",feedback:"A monopoly restricts output below the efficient level."},
{ id:3005,q:"The Price Maker challenges: 'Where is the loss?' Deadweight loss from monopoly represents...",options:["Transfers to firms","Lost gains from trade","Higher costs","Increased efficiency"],a:1,tag:"efficiency",type:"interpretation",objective:"LO12.3",feedback:"Deadweight loss is lost surplus from trades that no longer occur."},

// --- INTERACTION ---
{ id:3006,q:"The Price Maker observes: 'Markets do not stand alone.' What happens when a monopolist raises price significantly?",options:["No effect elsewhere","Demand for substitutes rises","Supply increases","Costs fall"],a:1,tag:"interaction",type:"interpretation",objective:"LO11.1",feedback:"Markets interact through substitutes, so higher monopoly prices can increase demand for substitute goods."},
{ id:3007,q:"The Price Maker presses: 'Trace the ripple.' A monopolist raises price on a key input good. What happens to firms using that input?",options:["Costs fall","Supply shifts left","Demand rises","No change"],a:1,tag:"interaction",type:"interpretation",objective:"LO11.1",feedback:"A higher input price raises production costs, shifting supply left."},
{ id:3008,q:"The Price Maker warns: 'Follow it through.' If substitute goods become more attractive due to monopoly pricing, what happens to the monopolist’s demand?",options:["Becomes perfectly elastic","Shifts left","Becomes vertical","Does not change"],a:1,tag:"interaction",type:"interpretation",objective:"LO11.1",feedback:"More attractive substitutes pull demand away from the monopolist."},

// --- FAILURE ---
{ id:3009,q:"The Price Maker admits: 'Even I break the system.' What type of issue does monopoly create?",options:["External benefit","Market failure","Public good","Efficient allocation"],a:1,tag:"failure",type:"definition",objective:"LO11.3",feedback:"Market power is a market failure because it prevents efficient allocation."},
{ id:3010,q:"The Price Maker challenges: 'Correct me if you can.' Why is monopoly considered inefficient?",options:["Too much output","Too little output relative to efficient level","Prices equal cost","No profit exists"],a:1,tag:"failure",type:"interpretation",objective:"LO12.3",feedback:"Monopoly underproduces relative to the efficient level."},
{ id:3011,q:"The Price Maker scoffs: 'Fix it then.' Which policy directly targets monopoly power?",options:["Subsidies","Antitrust enforcement","Tax cuts","Price increases"],a:1,tag:"failure",type:"interpretation",objective:"LO12.5",feedback:"Antitrust enforcement targets monopoly dominance and anticompetitive behavior."},

// --- STRATEGY ---
{ id:3012,q:"The Price Maker whispers: 'Others are watching.' What defines oligopoly behavior?",options:["Independent decisions","Strategic interdependence","Perfect competition","No rivals"],a:1,tag:"strategy",type:"definition",objective:"LO13.1",feedback:"Oligopoly firms must anticipate rival behavior."},
{ id:3013,q:"The Price Maker presses: 'Think ahead.' Why must firms consider competitors’ reactions?",options:["To reduce costs","Outcomes depend on rival responses","Demand disappears","Prices are fixed"],a:1,tag:"strategy",type:"interpretation",objective:"LO13.1",feedback:"In oligopoly, one firm’s payoff depends on how competitors respond."},
{ id:3014,q:"The Price Maker tests: 'Fail to think ahead.' If firms ignore competitor reactions, what is the likely outcome?",options:["Higher efficiency","Strategic mistakes","Perfect equilibrium","Guaranteed profit"],a:1,tag:"strategy",type:"interpretation",objective:"LO13.1",feedback:"Ignoring rival reactions leads to poor strategic decisions."},

// --- EQUITY ---
{ id:3015,q:"The Price Maker grins: 'Not everyone pays the same.' What concern arises with price discrimination?",options:["Efficiency only","Fairness and distribution","Cost reduction","Supply increase"],a:1,tag:"equity",type:"definition",objective:"LO11.5",feedback:"Charging different prices to different consumers can raise fairness and distribution concerns."},
{ id:3016,q:"The Price Maker challenges: 'Who bears the burden?' Charging higher prices to captive consumers raises what issue?",options:["Efficiency gain","Equity concern","Lower cost","Higher output"],a:1,tag:"equity",type:"interpretation",objective:"LO11.5",feedback:"Charging more to consumers with fewer alternatives raises equity concerns."},
{ id:3017,q:"The Price Maker presses: 'Is it justified?' If price discrimination increases output but treats consumers differently, what trade-off arises?",options:["Cost vs revenue","Equity vs efficiency","Supply vs demand","Short run vs long run"],a:1,tag:"equity",type:"interpretation",objective:"LO11.5",feedback:"Price discrimination can increase output while raising fairness concerns."}
],

finalBoss:[

// --- EFFICIENCY ---
{id:4000,q:"The Grand Strategist declares: 'Efficiency is achieved, not assumed.' In an Edgeworth Box, which condition signals that no mutually beneficial trade remains?",options:["Both people receive equal bundles","Both people have equal income","The individuals' marginal rates of substitution are equal","The allocation is inside the shaded lens of possible trades"],a:2,tag:"efficiency",type:"graph-integration",objective:"LO11.4",image:"Edgeworth11.4.png",feedback:"Pareto efficiency in an Edgeworth Box occurs where the individuals' indifference curves are tangent. At that point, their marginal rates of substitution are equal and no further mutually beneficial trade remains."},
{id:4001,q:"The Strategist presses: 'Read the lens.' In the shaded Edgeworth Box, point A lies inside a lens of possible trades. What does that imply?",options:["Point A is Pareto efficient","Mutually beneficial trades may still exist","The allocation is automatically equitable","Both people must receive identical bundles"],a:1,tag:"efficiency",type:"graph",objective:"LO11.4",image:"edgeworth11.2.png",feedback:"The shaded lens shows possible Pareto improvements. If point A lies inside that trading region, then at least one person can be made better off without making the other worse off."},
{id:4002,q:"The Grand Strategist concludes: 'Do not confuse movement with mastery.' If voluntary trade moves an allocation onto the contract curve, what has been achieved?",options:["Pareto efficiency, but not necessarily equity","Equity, but not necessarily efficiency","Equal utility for both people","Maximum production at minimum cost"],a:0,tag:"efficiency",type:"trap",objective:"LO11.4",feedback:"Moving to the contract curve achieves Pareto efficiency because no further mutually beneficial trade remains. It does not guarantee that the final allocation is fair."},

// --- POWER ---
{id:4003,q:"The Strategist observes: 'Power begins where competition ends.' A monopolist faces demand P = 120 - 2Q and MC = 40. MR = 120 - 4Q. What price does the monopolist charge?",options:["$40","$60","$80","$120"],a:2,tag:"power",type:"calculation",objective:"LO12.2",feedback:"Set MR = MC: 120 - 4Q = 40, so Q = 20. Then use demand: P = 120 - 2(20) = 80."},
{id:4004,q:"The Strategist presses: 'Power leaves a scar.' Why does a single-price monopolist create deadweight loss?",options:["It produces where price equals marginal cost","It produces less than the efficient quantity where willingness to pay equals marginal cost","It always earns zero economic profit","It sells every unit consumers value above marginal cost"],a:1,tag:"power",type:"integration",objective:"LO12.3",feedback:"A single-price monopolist restricts output below the efficient level. Some units that consumers value more than marginal cost are not produced, creating deadweight loss."},
{id:4005,q:"The Strategist narrows his gaze: 'Power lies in division.' A monopolist sells to two groups. Group A has elasticity of demand of 2, and Group B has elasticity of 6. What is the optimal pricing strategy?",options:["Charge the same price to both groups","Charge a higher price to Group B","Charge a higher price to Group A","Set price equal to marginal cost for both groups"],a:2,tag:"power",type:"calculation",objective:"LO12.4",feedback:"Group A has less elastic demand, so the monopolist can charge Group A a higher price. Less elastic consumers are less responsive to price increases."},

// --- STRATEGY ---
{id:4006,q:"The Strategist states: 'Rivals react.' In Cournot competition, Firm A increases output and Firm B reduces output, but not enough to fully offset Firm A. What happens to total output and price?",options:["Total output rises and price falls","Total output falls and price rises","Total output is unchanged and price is unchanged","Total output rises and price rises"],a:0,tag:"strategy",type:"multi-step",objective:"LO13.1",feedback:"Cournot quantities are strategic substitutes, so Firm B may reduce output when Firm A expands. But if the reduction does not fully offset Firm A's increase, total output rises and price falls."},
{id:4007,q:"The Strategist presses: 'Price competition changes when products differ.' Why do differentiated Bertrand firms usually charge prices above marginal cost?",options:["Products are not perfect substitutes, so each firm retains some market power","Consumers always buy from the lowest-price firm","Firms are required to set the same price","Differentiation eliminates demand"],a:0,tag:"strategy",type:"integration",objective:"LO13.2",feedback:"When products are differentiated, a firm does not lose the entire market by charging a slightly higher price. Differentiation softens price competition and allows price to remain above marginal cost."},
{id:4008,q:"The Strategist delivers the final test: 'Move first, shape the field.' Why can the Stackelberg leader earn more than the follower?",options:["The leader commits to output first and anticipates the follower's response","The follower chooses output first","Both firms must produce equal output","The leader always prices at marginal cost"],a:0,tag:"strategy",type:"interpretation",objective:"LO13.3",feedback:"The Stackelberg leader gains an advantage by committing to output first. The leader chooses output while anticipating how the follower will respond."},

// --- FAILURE ---
{id:4009,q:"The Strategist warns: 'Markets fail when signals break.' A factory's private marginal cost is $20, and each unit creates $8 of external harm. If the harm is ignored, what is social marginal cost?",options:["$12","$20","$28","$160"],a:2,tag:"failure",type:"calculation",objective:"LO11.3",feedback:"Social marginal cost equals private marginal cost plus external damage. Here, SMC = 20 + 8 = 28."},
{id:4010,q:"The Strategist presses: 'Competition alone is not salvation.' A market has many buyers and sellers, but firms dump waste into a river without paying for the damage. What should we conclude?",options:["Competition guarantees efficiency","The market can fail because external costs are ignored","The market is efficient if firms earn zero profit","Externalities only matter under monopoly"],a:1,tag:"failure",type:"trap",objective:"LO11.3",feedback:"Competition does not fix unpriced external costs. If firms do not pay for the damage they create, the market produces too much of the good."},
{id:4011,q:"The Strategist challenges: 'Lost surplus is not a transfer.' In monopoly, what does deadweight loss represent?",options:["Profit earned by the monopolist","Consumer spending transferred to the firm","Lost gains from trades that do not occur","Government tax revenue"],a:2,tag:"failure",type:"interpretation",objective:"LO12.3",feedback:"Deadweight loss is lost surplus from trades that would have benefited society but do not occur because monopoly output is restricted."},

// --- INTERACTION ---
{id:4012,q:"The Strategist observes: 'All markets are connected.' Demand for electric vehicles rises, increasing demand for lithium. Lithium prices rise, battery supply falls, and laptop producers face higher costs. What does this show?",options:["Only the electric vehicle market is affected","A demand shock can create spillovers through shared input markets","Laptop demand must have increased first","Battery producers must be monopolists"],a:1,tag:"interaction",type:"integration",objective:"LO11.1",feedback:"Lithium is a shared input. A demand shock in one market can raise input prices and shift costs in related markets."},
{id:4013,q:"The Strategist presses: 'Production and consumption need not match.' In the trade graph, why can the economy produce at point A but consume at point C?",options:["Trade allows production and consumption to differ","The PPF shifts outward immediately","Point C is inside the PPF","The economy ignores opportunity cost"],a:0,tag:"interaction",type:"graph-integration",objective:"LO11.4",image:"trade11.2.png",feedback:"With trade, an economy can specialize in production and then exchange along the world price line. That allows consumption to differ from production."},
{id:4014,q:"The Strategist warns: 'Follow the whole chain.' A drought reduces wheat supply, bread prices rise, cereal producers face higher input costs, and some consumers switch toward rice. What does this chain show?",options:["Only supply shifts matter","One market disturbance can affect complements, substitutes, and input markets","Demand curves never shift after supply shocks","All prices must return to their original levels"],a:1,tag:"interaction",type:"multi-step",objective:"LO11.1",feedback:"A shock in one market can ripple through related goods, substitutes, complements, and input markets. That is the general-equilibrium logic."},

// --- EQUITY ---
{id:4015,q:"The Strategist concludes: 'Efficiency is not fairness.' An allocation is Pareto efficient but gives almost everything to one person. What is the correct conclusion?",options:["It must be socially optimal","It may be efficient but still fail society's fairness goals","It is not Pareto efficient because it is unequal","It proves markets always fail"],a:1,tag:"equity",type:"trap",objective:"LO11.5",feedback:"Pareto efficiency does not guarantee fairness. An allocation can be efficient because no mutually beneficial trades remain, while still being highly unequal."},
{id:4016,q:"The Strategist presses: 'Choose the tradeoff.' A policy redistributes income from high-income consumers to low-income consumers but reduces total surplus. What does this illustrate?",options:["A Pareto improvement","An efficiency-equity tradeoff","A public good problem","A monopoly pricing strategy"],a:1,tag:"equity",type:"interpretation",objective:"LO11.5",feedback:"The policy may improve fairness, but if it reduces total surplus, it creates an efficiency-equity tradeoff."},
{id:4017,q:"The Strategist delivers judgment: 'Build the fairer world carefully.' According to the Second Welfare Theorem, how can society pursue a fairer efficient outcome?",options:["Redistribute initial endowments, then allow competitive trade","Ban trade after redistribution","Force all consumers to hold equal bundles","Set every price equal to average cost"],a:0,tag:"equity",type:"integration",objective:"LO11.5",feedback:"The Second Welfare Theorem separates distribution from exchange: society can redistribute initial endowments, then allow competitive trade to reach an efficient allocation."}
],

easy:[
{id:1,q:"If the price of steel rises, what happens to the supply of cars?",options:["Increases","Decreases","Stays the same","Becomes zero"],a:1,tag:"interaction",type:"interpretation",objective:"LO11.1",feedback:"Higher input costs reduce supply."},
{id:2,q:"If wages increase, firms will typically...",options:["Increase supply","Decrease supply","Increase demand","Do nothing"],a:1,tag:"interaction",type:"interpretation",objective:"LO11.1",feedback:"Higher costs shift supply left."},
{id:3,q:"When one market affects another, this is called...",options:["Isolation","Interaction","Equilibrium","Efficiency"],a:1,tag:"interaction",type:"definition",objective:"LO11.1",feedback:"Markets are interconnected."},
{id:4,q:"If the price of coffee rises, demand for tea will likely...",options:["Fall","Rise","Stay the same","Disappear"],a:1,tag:"interaction",type:"interpretation",objective:"LO11.1",feedback:"Substitutes increase demand."},
{id:5,q:"A decrease in input costs will...",options:["Decrease supply","Increase supply","Decrease demand","Do nothing"],a:1,tag:"interaction",type:"interpretation",objective:"LO11.1",feedback:"Lower costs increase supply."},
{id:6,q:"If two goods are complements and one price rises, demand for the other...",options:["Rises","Falls","Stays constant","Becomes elastic"],a:1,tag:"interaction",type:"interpretation",objective:"LO11.1",feedback:"Complements move together."},

{id:7,q:"If demand increases in a competitive market, price will...",options:["Fall","Rise","Stay constant","Disappear"],a:1,tag:"efficiency",type:"interpretation",objective:"LO11.2",feedback:"Demand shifts push price up."},
{id:8,q:"If supply increases, price will...",options:["Rise","Fall","Stay constant","Double"],a:1,tag:"efficiency",type:"interpretation",objective:"LO11.2",feedback:"More supply lowers price."},
{id:9,q:"Allocative efficiency occurs when...",options:["MR = MC","P = MC","ATC is minimized","Profit is zero"],a:1,tag:"efficiency",type:"definition",objective:"LO11.2",feedback:"Value equals cost."},
{id:10,q:"Competitive markets tend to be efficient because...",options:["Firms control prices","P = MC","Government sets output","Supply is fixed"],a:1,tag:"efficiency",type:"interpretation",objective:"LO11.2",feedback:"Competition forces P = MC."},
{id:11,q:"Total surplus is maximized when...",options:["P = MC","MR = MC","ATC = MC","Demand is flat"],a:0,tag:"efficiency",type:"definition",objective:"LO11.2",feedback:"Efficiency maximizes total surplus."},
{id:12,q:"Consumer surplus measures...",options:["Profit","Willingness to pay minus price","Cost minus price","Revenue"],a:1,tag:"efficiency",type:"definition",objective:"LO11.2",feedback:"Value to buyers."},
{id:13,q:"Producer surplus measures...",options:["Price minus cost","Profit","Revenue","Demand"],a:0,tag:"efficiency",type:"definition",objective:"LO11.2",feedback:"Value to sellers."},

{id:14,q:"Market failure occurs when...",options:["Prices rise","Markets are inefficient","Firms earn profit","Demand shifts"],a:1,tag:"failure",type:"definition",objective:"LO11.3",feedback:"Failure = inefficiency."},
{id:15,q:"Externalities are...",options:["Internal costs","Costs or benefits affecting third parties","Prices","Demand shifts"],a:1,tag:"failure",type:"definition",objective:"LO11.3",feedback:"Spillovers outside the market."},
{id:16,q:"A negative externality causes...",options:["Too little production","Too much production","Efficient output","Zero output"],a:1,tag:"failure",type:"interpretation",objective:"LO11.3",feedback:"Overproduction problem."},
{id:17,q:"Deadweight loss represents...",options:["Lost surplus","Profit","Revenue","Cost"],a:0,tag:"failure",type:"definition",objective:"LO11.3",feedback:"Value lost from inefficiency."},

{id:18,q:"A monopolist is a firm that...",options:["Takes price","Controls price","Earns zero profit","Faces many competitors"],a:1,tag:"power",type:"definition",objective:"LO12.1",feedback:"Price maker."},
{id:19,q:"Monopolies restrict output to...",options:["Increase efficiency","Increase profits","Eliminate costs","Match competition"],a:1,tag:"power",type:"interpretation",objective:"LO12.3",feedback:"Less output, higher price."},
{id:20,q:"Compared to competition, monopoly price is...",options:["Lower","Higher","Equal","Zero"],a:1,tag:"power",type:"interpretation",objective:"LO12.3",feedback:"Market power raises price."},
{id:21,q:"Monopoly profit maximization occurs where...",options:["P = MC","MR = MC","ATC = MC","Demand is highest"],a:1,tag:"power",type:"definition",objective:"LO12.2",feedback:"Same rule, different outcome."},
{id:22,q:"A natural monopoly exists when...",options:["Many firms are efficient","One firm has lowest cost","Demand is low","Prices fall"],a:1,tag:"power",type:"definition",objective:"LO12.1",feedback:"Economies of scale dominate."},
{id:23,q:"Governments regulate monopolies to...",options:["Increase profits","Reduce inefficiency","Eliminate supply","Raise prices"],a:1,tag:"power",type:"interpretation",objective:"LO12.5",feedback:"Control market power."},

{id:24,q:"Cournot competition involves firms choosing...",options:["Prices","Output","Costs","Wages"],a:1,tag:"strategy",type:"definition",objective:"LO13.1",feedback:"Quantity competition."},
{id:25,q:"Bertrand competition involves firms choosing...",options:["Output","Prices","Capacity","Technology"],a:1,tag:"strategy",type:"definition",objective:"LO13.1",feedback:"Price competition."},
{id:26,q:"In Bertrand competition with identical goods, prices tend to...",options:["Rise","Fall to marginal cost","Stay high","Become random"],a:1,tag:"strategy",type:"interpretation",objective:"LO13.1",feedback:"Price war → P = MC."},
{id:27,q:"A first mover advantage means...",options:["Moving later is better","First firm gains advantage","No firm benefits","Prices fall"],a:1,tag:"strategy",type:"definition",objective:"LO13.3",feedback:"Commitment matters."},
{id:28,q:"Product differentiation gives firms...",options:["No power","Some market power","Perfect competition","Zero demand"],a:1,tag:"strategy",type:"interpretation",objective:"LO13.2",feedback:"Differentiation softens competition."},

{id:29,q:"Equity refers to...",options:["Efficiency","Fairness","Profit","Output"],a:1,tag:"equity",type:"definition",objective:"LO11.5",feedback:"Fair distribution."},
{id:30,q:"Efficiency refers to...",options:["Fairness","Maximizing total surplus","Equal income","Low prices"],a:1,tag:"equity",type:"definition",objective:"LO11.2",feedback:"Max total value."},
{id:31,q:"An efficiency-equity tradeoff means...",options:["Both always increase","Improving fairness may reduce efficiency","Efficiency always rises","Markets ignore fairness"],a:1,tag:"equity",type:"interpretation",objective:"LO11.5",feedback:"Tradeoffs are real."},
{id:32,q:"Redistribution policies aim to...",options:["Increase efficiency","Increase equity","Increase monopoly power","Reduce demand"],a:1,tag:"equity",type:"interpretation",objective:"LO11.5",feedback:"Shift toward fairness."},

{id:33,q:"In an Edgeworth Box, gains from trade exist when...",options:["MRS is equal","MRS differs between individuals","Prices are equal","Utility is maximized"],a:1,tag:"efficiency",type:"definition",objective:"LO11.4",feedback:"Different MRS → gains from trade."},
{id:34,q:"If two individuals have identical MRS, what does this imply?",options:["Gains from trade exist","Allocation is inefficient","No further gains from trade","Prices must change"],a:2,tag:"efficiency",type:"interpretation",objective:"LO11.4",feedback:"Equal MRS → Pareto efficient."},

{id:35,q:"A barrier to entry allows a firm to...",options:["Increase competition","Prevent new firms from entering","Reduce costs","Increase demand"],a:1,tag:"power",type:"definition",objective:"LO12.1",feedback:"Protects market power."},
{id:36,q:"Which is an example of a barrier to entry?",options:["Low prices","Patents","High demand","Perfect information"],a:1,tag:"power",type:"interpretation",objective:"LO12.1",feedback:"Legal barriers restrict entry."},
{id:37,q:"A firm charges an entry fee plus a per-unit price. This is called...",options:["Perfect competition","Two-part tariff","Price ceiling","Subsidy"],a:1,tag:"power",type:"definition",objective:"LO12.4",feedback:"Fixed fee + usage price."},
{id:38,q:"A two-part tariff allows firms to...",options:["Reduce output","Capture consumer surplus","Increase costs","Eliminate demand"],a:1,tag:"power",type:"interpretation",objective:"LO12.4",feedback:"Extracts surplus through entry fee."}
],

medium:[
{id:100,q:"Demand for electric cars rises. Lithium batteries are an input. What happens to lithium prices?",options:["Fall","Rise","Stay constant","Become zero"],a:1,tag:"interaction",type:"interpretation",objective:"LO11.1",feedback:"Derived demand increases input prices."},
{id:101,q:"If wages rise in one industry, what happens to wages in competing labor markets?",options:["Rise","Fall","Stay constant","Double"],a:1,tag:"interaction",type:"interpretation",objective:"LO11.1",feedback:"Labor shifts across markets—greater supply lowers wages elsewhere."},
{id:102,q:"If P > MC in a competitive market, what should happen?",options:["Output decreases","Output increases","Nothing changes","Firms exit"],a:1,tag:"efficiency",type:"interpretation",objective:"LO11.2",feedback:"Value exceeds cost—expand production."},
{id:103,q:"A market has P = 10 and MC = 6. What does this imply?",options:["Efficient","Underproduction","Overproduction","Cannot determine"],a:1,tag:"efficiency",type:"interpretation",objective:"LO11.2",feedback:"P > MC → underproduction."},
{id:104,q:"Two consumers have MRS of 2 and 6. What does this imply?",options:["Efficient allocation","No gains from trade","Gains from trade exist","Prices are equal"],a:2,tag:"efficiency",type:"interpretation",objective:"LO11.4",feedback:"Different valuations = gains from trade."},
{id:105,q:"A monopolist has MR = 20 and MC = 25. What should it do?",options:["Increase output","Decrease output","Keep output constant","Raise price"],a:1,tag:"power",type:"calculation",objective:"LO12.2",feedback:"MR < MC → reduce output."},
{id:106,q:"Why is monopoly price greater than marginal cost?",options:["Costs increase","Demand curve lies above MR","Demand is flat","Government forces it"],a:1,tag:"power",type:"interpretation",objective:"LO12.2",feedback:"Downward-sloping demand → MR < P."},
{id:107,q:"A monopolist perfectly price discriminates. What happens to output?",options:["Falls","Stays same","Rises to efficient level","Becomes zero"],a:2,tag:"power",type:"interpretation",objective:"LO12.4",feedback:"Perfect price discrimination eliminates DWL."},
{id:108,q:"In Cournot competition, if one firm increases output, rivals will...",options:["Increase output","Decrease output","Exit","Do nothing"],a:1,tag:"strategy",type:"interpretation",objective:"LO13.1",feedback:"Outputs are strategic substitutes."},
{id:109,q:"In Bertrand competition with identical goods and MC = 5, equilibrium price is...",options:["10","5","0","15"],a:1,tag:"strategy",type:"calculation",objective:"LO13.1",feedback:"Price competition drives P = MC."},
{id:110,q:"If firms become more differentiated, what happens to pricing?",options:["Falls to MC","Rises above MC","Becomes zero","Stays constant"],a:1,tag:"strategy",type:"interpretation",objective:"LO13.2",feedback:"Differentiation softens competition."},
{id:111,q:"An allocation is Pareto efficient. Can it still be unequal?",options:["No","Yes","Only with government","Only with monopoly"],a:1,tag:"equity",type:"interpretation",objective:"LO11.5",feedback:"Efficiency says nothing about fairness."},
{id:112,q:"Government redistributes income before trade. What happens?",options:["Always inefficient","Efficient outcome still possible","Markets fail","Prices collapse"],a:1,tag:"equity",type:"interpretation",objective:"LO11.5",feedback:"Second Welfare Theorem."},
{id:113,q:"A firm ignores pollution costs. What happens to output?",options:["Too low","Too high","Efficient","Zero"],a:1,tag:"failure",type:"interpretation",objective:"LO11.3",feedback:"External costs ignored → overproduction."},
{id:114,q:"A non-rival, non-excludable good leads to...",options:["Overproduction","Efficient provision","Underproduction","Zero demand"],a:2,tag:"failure",type:"interpretation",objective:"LO11.3",feedback:"Free-rider problem → underprovision."},
{id:115,q:"Information asymmetry leads to...",options:["Efficiency","Perfect competition","Market failure","Equilibrium"],a:2,tag:"failure",type:"definition",objective:"LO11.3",feedback:"Unequal information disrupts markets."},
{id:116,q:"If social cost exceeds private cost, output is...",options:["Too low","Too high","Efficient","Zero"],a:1,tag:"failure",type:"interpretation",objective:"LO11.3",feedback:"External costs → overproduction."},
{id:117,q:"Deadweight loss occurs when...",options:["All trades occur","Some beneficial trades are prevented","Prices equal MC","Supply equals demand"],a:1,tag:"failure",type:"interpretation",objective:"LO11.3",feedback:"Lost gains from trade."},
{id:118,q:"Where does a monopolist get price from?",options:["Supply","Demand","ATC","MC"],a:1,tag:"power",type:"interpretation",objective:"LO12.2",feedback:"Price comes from demand curve."},
{id:119,q:"Why is MR less than price for a monopolist?",options:["MR = P","Price cut applies to all units","MR > P","MR = 0"],a:1,tag:"power",type:"interpretation",objective:"LO12.2",feedback:"Lowering price affects all units sold."},
{id:120,q:"If P = 20 and MC = 10 under monopoly, output is...",options:["Efficient","Too low","Too high","Zero"],a:1,tag:"power",type:"interpretation",objective:"LO12.3",feedback:"P > MC → underproduction."},
{id:121,q:"A firm with falling ATC across output is...",options:["Perfect competition","Monopolistic competition","Natural monopoly","Oligopoly"],a:2,tag:"power",type:"definition",objective:"LO12.1",feedback:"Economies of scale dominate."},
{id:122,q:"Separating customers by willingness to pay is...",options:["Bundling","Price discrimination","Collusion","Regulation"],a:1,tag:"power",type:"definition",objective:"LO12.4",feedback:"Charging different prices to different groups."},
{id:123,q:"A firm charges a fixed fee plus per-unit price. This is...",options:["Market separation","Two-part tariff","Perfect competition","Limit pricing"],a:1,tag:"power",type:"definition",objective:"LO12.4",feedback:"Entry fee + usage price."},
{id:124,q:"In Cournot, output decisions are...",options:["Independent","Strategic","Random","Fixed"],a:1,tag:"strategy",type:"definition",objective:"LO13.1",feedback:"Firms react to each other."},
{id:125,q:"Cournot output relative to monopoly is...",options:["Lower","Higher","Equal","Zero"],a:1,tag:"strategy",type:"interpretation",objective:"LO13.1",feedback:"More competition → more output."},
{id:126,q:"Capacity constraints in Bertrand lead to prices...",options:["Equal to MC","Above MC","Zero","Random"],a:1,tag:"strategy",type:"interpretation",objective:"LO13.2",feedback:"Limits soften price competition."},
{id:127,q:"A Nash equilibrium occurs when...",options:["Firms cooperate","Each best responds","Prices identical","Output maximized"],a:1,tag:"strategy",type:"definition",objective:"LO13.1",feedback:"No incentive to deviate."},
{id:128,q:"First mover advantage exists because...",options:["Lower cost","Commitment shapes rival response","Better demand","Government support"],a:1,tag:"strategy",type:"interpretation",objective:"LO13.3",feedback:"Leader influences follower behavior."},
{id:129,q:"Collusion is harder with many firms because...",options:["More profit","Harder coordination","Lower demand","More efficiency"],a:1,tag:"strategy",type:"interpretation",objective:"LO13.1",feedback:"More firms = harder to coordinate."},
{id:130,q:"Pareto efficiency means...",options:["Equal income","No gains from trade","Max output","Stable prices"],a:1,tag:"efficiency",type:"definition",objective:"LO11.4",feedback:"No one can improve without harm."},
{id:131,q:"Moving to the contract curve means...",options:["Inefficiency","All gains realized","Lower output","Higher prices"],a:1,tag:"efficiency",type:"interpretation",objective:"LO11.4",feedback:"All mutually beneficial trades exhausted."},
{id:132,q:"Efficient allocation may be undesirable because...",options:["Too much output","Unequal distribution","High prices","Low cost"],a:1,tag:"equity",type:"interpretation",objective:"LO11.5",feedback:"Efficiency ignores fairness."},
{id:133,q:"Second Welfare Theorem suggests equity via...",options:["Price controls","Redistribution of endowments","Lower output","Eliminating markets"],a:1,tag:"equity",type:"interpretation",objective:"LO11.5",feedback:"Adjust starting point, then trade."},
{id:134,q:"Removing barriers to entry leads to...",options:["Higher prices","Prices toward MC","Lower output","Zero demand"],a:1,tag:"power",type:"interpretation",objective:"LO12.1",feedback:"Competition increases."},
{id:135,q:"A high entry fee + low price aims to...",options:["Reduce demand","Capture surplus","Raise costs","Eliminate competition"],a:1,tag:"power",type:"interpretation",objective:"LO12.4",feedback:"Two-part tariff extracts surplus."},
{id:136,q:"If usage price = MC under two-part tariff, output is...",options:["Too low","Too high","Efficient","Zero"],a:2,tag:"power",type:"interpretation",objective:"LO12.4",feedback:"Efficient quantity achieved."}
],

hard:[
{id:200,q:"A surge in demand for electric vehicles raises the price of lithium. Battery producers cut output, which then affects laptop production. What does this illustrate?",options:["A single-market adjustment only","General equilibrium spillovers across related markets","Monopoly pricing in batteries","A movement along the laptop demand curve"],a:1,tag:"interaction",type:"interpretation",objective:"LO 11.1 — Related market disturbances",feedback:"A shock in one market can cascade through related input and output markets."},
{id:201,q:"A new health study raises demand for tomatoes. Tomatoes and cucumbers are complements, and tomato farms hire more workers away from cucumber farms. What is the most likely long-run result?",options:["Tomato prices rise forever while cucumber prices never change","Tomato and cucumber markets both adjust as prices and wages change across markets","Only the tomato market changes because consumer demand began there","Worker wages are irrelevant because labor markets are separate"],a:1,tag:"interaction",type:"trap",objective:"LO 11.1 — Related market disturbances",feedback:"General equilibrium means product and labor markets adjust together."},
{id:202,q:"A tariff raises the domestic price of imported steel. Which downstream effect is most likely?",options:["Car supply shifts right because domestic firms gain certainty","Car supply shifts left because an input became more expensive","Car demand shifts right because steel is scarcer","Car prices must fall because steel producers earn more"],a:1,tag:"interaction",type:"interpretation",objective:"LO 11.1 — Related market disturbances",feedback:"Higher input costs reduce supply in industries using that input."},
{id:203,q:"Suppose coffee and pastries are complements. A productivity improvement lowers the cost of producing coffee. Which sequence is most plausible?",options:["Coffee supply rises, coffee price falls, demand for pastries rises","Coffee demand falls, pastry demand falls, both prices rise","Coffee price rises, pastry supply falls, labor exits both industries","Nothing happens outside the coffee market"],a:0,tag:"interaction",type:"default",objective:"LO 11.1 — Related market disturbances",feedback:"Lower coffee cost spills over into the complementary pastry market."},
{id:204,q:"An increase in demand for restaurant meals raises wages for cooks. Some workers leave retail jobs to become cooks. What happens first in retail labor markets?",options:["Retail labor supply falls, tending to raise retail wages","Retail labor supply rises, lowering retail wages","Retail output rises immediately because cooks consume more","Retail demand disappears because labor moved"],a:0,tag:"interaction",type:"trap",objective:"LO 11.1 — Related market disturbances",feedback:"Workers leaving retail reduce labor supply there, putting upward pressure on wages."},
{id:205,q:"Two industries use the same specialized chip. Demand for gaming consoles spikes, raising chip prices. A student says only console prices will change because laptops are a different market. What is wrong with that reasoning?",options:["Chip prices affect only consumers, not firms","Shared inputs link markets, so laptop production conditions also change","Laptop demand determines chip prices, not console demand","Different final goods can never be connected"],a:1,tag:"interaction",type:"trap",objective:"LO 11.1 — Related market disturbances",feedback:"Shared inputs are one of the clearest channels linking separate markets."},
{id:206,q:"If an economy moves from a point inside the PPF to a point on the PPF but not to the highest attainable indifference curve, what has improved?",options:["Allocative efficiency only","Technical efficiency only","Equity only","Nothing has improved"],a:1,tag:"efficiency",type:"interpretation",objective:"LO 11.2 — Competitive markets and efficiency",feedback:"Moving onto the PPF fixes waste in production, but not necessarily consumer satisfaction."},
{id:207,q:"At a candidate allocation, the slope of the PPF does not equal the slope of the indifference curve. What does that imply?",options:["Consumers and producers are perfectly aligned","The allocation is not allocatively efficient","The economy is inside the PPF","The market must be monopolized"],a:1,tag:"efficiency",type:"trap",objective:"LO 11.2 — Competitive markets and efficiency",feedback:"Efficiency requires opportunity cost to match willingness to trade."},
{id:208,q:"Two people trade goods until their MRS values are equal. What has been achieved?",options:["Equality of income","Pareto efficiency in exchange","Productive efficiency in production","A guarantee of fairness"],a:1,tag:"efficiency",type:"definition",objective:"LO 11.4 — Pareto efficiency",feedback:"Equal MRS means no mutually beneficial trade remains."},
{id:209,q:"A competitive market clears, but at the equilibrium output P exceeds MC. What should we conclude?",options:["The market is efficient because quantity demanded equals quantity supplied","The market is underproducing relative to the efficient level","The market is overproducing because firms earn profit","Nothing can be concluded without ATC"],a:1,tag:"efficiency",type:"trap",objective:"LO 11.2 — Competitive markets and efficiency",feedback:"Market clearing alone is not enough. Efficiency requires P = MC."},
{id:210,q:"A good has price 18 and marginal cost 12 at the current output. What adjustment would move the market toward allocative efficiency?",options:["Reduce output because costs are positive","Increase output because willingness to pay exceeds marginal cost","Hold output constant because the market already clears","Raise fixed costs so ATC matches price"],a:1,tag:"efficiency",type:"calculation",objective:"LO 11.2 — Competitive markets and efficiency",feedback:"If P > MC, additional units are worth more than they cost to make."},
{id:211,q:"A planner chooses a point on the PPF that yields less utility than another feasible point on the same PPF. This point is...",options:["Productively and allocatively efficient","Productively efficient but allocatively inefficient","Allocatively efficient but technically inefficient","Pareto superior to all other points"],a:1,tag:"efficiency",type:"trap",objective:"LO 11.2 — Competitive markets and efficiency",feedback:"Being on the PPF does not guarantee the best mix of goods."},
{id:212,q:"Trade moves an economy from an initial endowment to a point on the contract curve. What is true at the final point?",options:["At least one more mutually beneficial trade still exists","No one can be made better off without harming someone else","The allocation must also be equitable","Each person has the same bundle"],a:1,tag:"efficiency",type:"interpretation",objective:"LO 11.4 — Pareto efficiency",feedback:"The contract curve is the set of Pareto efficient allocations."},
{id:213,q:"A factory dumps waste into a river, and downstream fishers bear the damage. If the factory ignores that damage, which comparison is correct?",options:["Private cost equals social cost","Private cost exceeds social cost","Social cost exceeds private cost","Marginal benefit exceeds all costs automatically"],a:2,tag:"failure",type:"definition",objective:"LO 11.3 — Market failure",feedback:"Unpriced external harm means social cost is higher than private cost."},
{id:214,q:"A city installs streetlights funded voluntarily. Many residents enjoy the lights whether or not they contribute, so contributions stay low. What market failure is this?",options:["Imperfect competition","Public goods underprovision due to free-riding","Natural monopoly","Efficient market separation"],a:1,tag:"failure",type:"interpretation",objective:"LO 11.3 — Market failure",feedback:"Non-excludability and non-rivalry create free-rider problems."},
{id:215,q:"A student says a market with many buyers and sellers must be efficient. Which case most clearly disproves that claim?",options:["A perfectly competitive wheat market","A polluted river caused by factory output","A market with falling ATC","A firm entering because profits exist"],a:1,tag:"failure",type:"trap",objective:"LO 11.3 — Market failure",feedback:"Externalities can destroy efficiency even when competition exists."},
{id:216,q:"If consumers cannot tell whether used cars are high or low quality, mutually beneficial trades may fail to occur. This is best classified as...",options:["A public good problem","Imperfect information causing market failure","A natural monopoly problem","A case of allocative efficiency"],a:1,tag:"failure",type:"interpretation",objective:"LO 11.3 — Market failure",feedback:"Asymmetric information can block efficient exchange."},
{id:217,q:"Suppose the private marginal cost of a product is 8, but the external damage per unit is 5. What is the social marginal cost?",options:["3","8","13","40"],a:2,tag:"failure",type:"calculation",objective:"LO 11.3 — Market failure",feedback:"Social marginal cost adds the external harm to private cost."},
{id:218,q:"A vaccine provides private benefit to the buyer and external benefit to others by reducing spread. If consumers ignore that external benefit, the market outcome will likely involve...",options:["Too much output","Too little output","Efficient output","A natural monopoly"],a:1,tag:"failure",type:"trap",objective:"LO 11.3 — Market failure",feedback:"Positive externalities lead to underproduction relative to the social optimum."},
{id:219,q:"A monopolist faces demand P = 100 - Q and marginal cost MC = 20. At the profit-maximizing output, which condition must hold?",options:["P = MC","MR = MC","ATC = MC","Demand = supply"],a:1,tag:"power",type:"definition",objective:"LO 12.2 — Monopoly price and output",feedback:"The monopoly still maximizes profit where marginal revenue equals marginal cost."},
{id:220,q:"A monopolist has demand P = 100 - Q and MC = 20. Marginal revenue is MR = 100 - 2Q. What is the profit-maximizing quantity?",options:["20","40","60","80"],a:1,tag:"power",type:"calculation",objective:"LO 12.2 — Monopoly price and output",feedback:"Set MR = MC: 100 - 2Q = 20, so Q = 40."},
{id:221,q:"Using the previous monopoly setup with Q = 40, what price does the monopolist charge?",options:["20","40","60","80"],a:2,tag:"power",type:"calculation",objective:"LO 12.2 — Monopoly price and output",feedback:"Plug Q = 40 into demand: P = 100 - 40 = 60."},
{id:222,q:"A student argues monopoly is inefficient only when the monopolist earns positive profit. What is wrong with that claim?",options:["Monopoly is inefficient whenever P > MC, even if profit is zero or negative","Any firm with zero profit is efficient","Profits determine whether MR equals MC","Monopoly is efficient if fixed costs are high"],a:0,tag:"power",type:"trap",objective:"LO 12.3 — Problems with monopoly",feedback:"The inefficiency comes from output restriction, not from accounting profit alone."},
{id:223,q:"A monopolist can perfectly price discriminate. Compared with single-price monopoly, output will...",options:["Fall because each unit gets a different price","Stay the same because market power is unchanged","Rise to the efficient level where willingness to pay equals MC","Become lower than competitive output"],a:2,tag:"power",type:"interpretation",objective:"LO 12.4 — Monopoly pricing strategies",feedback:"Perfect price discrimination removes deadweight loss by expanding output."},
{id:224,q:"A movie theater charges students less than non-students for the same showing. For this to work as profit-maximizing price discrimination, the theater must be able to...",options:["Eliminate all fixed costs","Prevent resale and separate customer groups","Make demand perfectly elastic","Force both groups to buy the same quantity"],a:1,tag:"power",type:"interpretation",objective:"LO 12.4 — Monopoly pricing strategies",feedback:"Price discrimination requires segmentation and limited arbitrage."},
{id:225,q:"A utility company is regulated under marginal-cost pricing even though marginal cost is below average cost. What is the likely result?",options:["The firm earns excess profit","The firm incurs losses unless subsidized","The firm produces too little","The firm becomes perfectly competitive"],a:1,tag:"power",type:"trap",objective:"LO 12.5 — Natural monopoly regulation",feedback:"For a natural monopoly, P = MC can imply price below AC."},
{id:226,q:"A monopolist charges an entry fee plus a per-unit price equal to marginal cost. Why can this raise profit?",options:["It creates deadweight loss on purpose","It captures consumer surplus through the fixed fee while keeping usage high","It forces resale","It makes demand more elastic"],a:1,tag:"power",type:"trap",objective:"LO 12.4 — Monopoly pricing strategies",feedback:"Two-part pricing can mimic some gains from price discrimination."},
{id:227,q:"In a two-firm Cournot market, each firm chooses output knowing total output affects price. Why is the Cournot outcome not as restrictive as monopoly?",options:["Each firm ignores the effect of its output on the other firm’s profit","Each firm sets price equal to MC directly","Collusion is legally required","Demand becomes perfectly elastic"],a:0,tag:"strategy",type:"trap",objective:"LO 13.1 — Cournot and Bertrand behavior",feedback:"Each firm internalizes only part of the price effect, so total output exceeds monopoly output."},
{id:228,q:"In Bertrand competition with identical goods and constant MC, why does price tend to fall to marginal cost?",options:["Each firm can gain the whole market by slightly undercutting a higher rival price","Firms coordinate on the monopoly price","Consumers prefer the highest price","Output is fixed by assumption"],a:0,tag:"strategy",type:"interpretation",objective:"LO 13.1 — Cournot and Bertrand behavior",feedback:"Undercutting pressure drives price down until no profitable cut remains."},
{id:229,q:"Two Bertrand firms sell differentiated goods. One firm raises its price. What is the best-response logic for the rival?",options:["Also tends to raise price because some consumers shift toward it","Must cut price to zero immediately","Must exit because demand becomes negative","Faces no change in demand"],a:0,tag:"strategy",type:"interpretation",objective:"LO 13.2 — Capacity constraints and product differentiation",feedback:"Differentiation softens competition and makes upward-sloping best responses possible."},
{id:230,q:"A cartel agreement in a repeated game is easier to sustain when...",options:["There are many firms and little chance of future interaction","Firms are patient and expect the game to continue","Products are homogeneous and one-shot","Detection of cheating takes longer and firms are impatient"],a:1,tag:"strategy",type:"trap",objective:"LO 13.1 — Cournot and Bertrand behavior",feedback:"Patience and future punishment make collusion more stable."},
{id:231,q:"Suppose a grim-trigger collusive arrangement requires g ≥ 1/2 to deter cheating. If g = 0.4, what follows?",options:["Collusion is stable","Cheating is profitable, so collusion is not sustainable","Price must equal monopoly price forever","Cournot output becomes efficient"],a:1,tag:"strategy",type:"calculation",objective:"LO 13.1 — Cournot and Bertrand behavior",feedback:"If continuation is too unlikely, future punishment is too weak."},
{id:232,q:"In a Stackelberg model, the leader commits to output first. Why does the leader often earn more than the follower?",options:["The follower must match output exactly","The leader chooses output anticipating the follower’s best response","The leader faces a flatter demand curve","The follower is forced to price at MC"],a:1,tag:"strategy",type:"interpretation",objective:"LO 13.3 — First mover advantage",feedback:"Commitment gives the leader a strategic advantage."},
{id:233,q:"An incumbent threatens a low price to deter entry, but the low price can be reversed immediately after entry decisions are made. Why may this threat fail?",options:["Price is not a sunk commitment","Demand becomes perfectly inelastic","Entry never depends on expected future prices","Incumbents cannot lower prices"],a:0,tag:"strategy",type:"trap",objective:"LO 13.3 — First mover advantage",feedback:"Without commitment, limit pricing threats may not be credible."},
{id:234,q:"Two firms play Bertrand with MC = 12 and identical goods. If both charge 18, what profitable deviation exists for one firm?",options:["Raise price to 20","Lower price slightly below 18 to capture the market","Keep price unchanged because 18 is Nash","Set price below 12 permanently"],a:1,tag:"strategy",type:"trap",objective:"LO 13.1 — Cournot and Bertrand behavior",feedback:"Any price above MC invites undercutting in the homogeneous Bertrand model."},
{id:235,q:"An allocation on the contract curve gives one person much more than the other. Which statement is correct?",options:["It is inefficient because the bundles are unequal","It may be efficient even though it is inequitable","It must be both fair and efficient","It cannot result from voluntary trade"],a:1,tag:"equity",type:"trap",objective:"LO 11.5 — Efficiency and equity",feedback:"Pareto efficiency does not guarantee fairness."},
{id:236,q:"A social planner wants a fairer outcome without sacrificing the efficiency of competitive trade. According to the Second Welfare Theorem, the best general approach is to...",options:["Fix all market prices directly","Redistribute initial endowments, then allow competitive trade","Ban voluntary exchange","Require equal quantities of all goods"],a:1,tag:"equity",type:"interpretation",objective:"LO 11.5 — Efficiency and equity",feedback:"Separate distribution from the trading process itself."},
{id:237,q:"Suppose Smith would never voluntarily trade from his initial endowment to the planner’s preferred allocation, even though the planner views it as fair. What core problem does this illustrate?",options:["Efficiency automatically creates equity","Equity goals may require coercion or redistribution of endowments","Markets cannot reach the contract curve","All fair allocations are inefficient"],a:1,tag:"equity",type:"trap",objective:"LO 11.5 — Efficiency and equity",feedback:"Fairness often cannot be imposed through voluntary trade alone."},
{id:238,q:"A tax-transfer policy reduces inequality but also discourages work effort and shrinks total surplus. This is an example of...",options:["A Pareto improvement","An efficiency-equity tradeoff","A failure of monopoly regulation","A proof that fairness is impossible"],a:1,tag:"equity",type:"interpretation",objective:"LO 11.5 — Efficiency and equity",feedback:"Improving distribution can come at the cost of efficiency."},
{id:239,q:"An outcome is Pareto efficient, but one person holds nearly all resources. What can we conclude?",options:["The outcome must be socially desirable","The outcome is efficient, but society may still reject it on equity grounds","The outcome is inefficient because wealth is concentrated","The contract curve has been violated"],a:1,tag:"equity",type:"default",objective:"LO 11.5 — Efficiency and equity",feedback:"Efficiency answers one question. Fairness answers another."},
{id:240,q:"Two individuals trade until their MRS are equal. What does this guarantee?",options:["Equal income","Pareto efficiency","Maximum production","Perfect equality"],a:1,tag:"efficiency",type:"definition",objective:"LO 11.4 — Pareto efficiency",feedback:"No further gains from trade remain."},
{id:241,q:"An allocation is on the contract curve but highly unequal. What is true?",options:["It is inefficient","It is efficient but may be inequitable","It must be fair","Trade must stop"],a:1,tag:"equity",type:"trap",objective:"LO 11.5 — Efficiency and equity",feedback:"Efficiency does not imply fairness."},
{id:242,q:"A monopolist earns persistent profit because of patents and control of key resources. What is the source of power?",options:["Demand shifts","Barriers to entry","Efficiency","Elasticity"],a:1,tag:"power",type:"interpretation",objective:"LO 12.1 — Sources of monopoly power",feedback:"Barriers prevent competition."},
{id:243,q:"If barriers to entry suddenly disappear in a monopoly market, what happens in the long run?",options:["Prices rise","Prices fall and output increases","Demand disappears","Costs rise"],a:1,tag:"power",type:"multi-step",objective:"LO 12.1 — Sources of monopoly power",feedback:"Entry erodes market power."},
{id:244,q:"A monopolist charges P = MC and a fixed entry fee equal to consumer surplus. What is the result?",options:["Deadweight loss","Efficient output and full surplus extraction","Zero output","Perfect competition"],a:1,tag:"power",type:"trap",objective:"LO 12.4 — Monopoly pricing strategies",feedback:"Two-part tariff can achieve efficiency while capturing surplus."},
{id:245,q:"Why is a two-part tariff often more profitable than a single price monopoly?",options:["It reduces costs","It increases demand","It captures more consumer surplus","It eliminates competition"],a:2,tag:"power",type:"interpretation",objective:"LO 12.4 — Monopoly pricing strategies",feedback:"Firms extract surplus beyond per-unit pricing."},
{id:246,q:"A hamburger market is linked to the labor market for hamburger workers. If the price of a substitute good falls, reducing demand for hamburgers, what is the most likely chain of effects?",options:["Hamburger demand falls, hamburger output falls, and labor demand for hamburger workers falls","Hamburger supply rises, hamburger output rises, and labor demand rises","Hamburger demand rises because substitutes became cheaper","Only the labor market changes because product markets and labor markets are unrelated"],a:0,tag:"interaction",type:"multi-step",objective:"LO11.1",feedback:"A lower price for a substitute reduces demand for hamburgers. Lower hamburger demand reduces output, which also lowers demand for workers in that market."},
{id:247,q:"A market currently has excess demand at the posted price. A point on the graph shows a bundle traded before adjustment, but equilibrium occurs elsewhere. What should students identify as the efficient market outcome?",options:["The traded bundle because all trades are efficient","The equilibrium point where quantity demanded equals quantity supplied","The highest quantity shown on the graph","The point with the greatest consumer surplus only"],a:1,tag:"efficiency",type:"graph-interpretation",objective:"LO11.2",feedback:"A traded bundle during adjustment is not necessarily the final efficient outcome. Competitive equilibrium occurs where quantity demanded equals quantity supplied."},
{id:248,q:"In an Edgeworth Box, Johnny and Sunny are at a point where their indifference curves cross rather than touch. What does this imply?",options:["The allocation is Pareto efficient","There are still mutually beneficial trades available","The allocation must be equitable","Both individuals have identical preferences"],a:1,tag:"efficiency",type:"graph-interpretation",objective:"LO11.4",feedback:"When indifference curves cross, the allocation is not on the contract curve. There are still trades that can make at least one person better off without making the other worse off."},
{id:249,q:"An Edgeworth Box shows two possible final allocations. One is on the contract curve but gives one person much more than the other. What is the best interpretation?",options:["The allocation is inefficient because it is unequal","The allocation may be Pareto efficient even if it is inequitable","The allocation must be both fair and efficient","The allocation cannot occur after voluntary trade"],a:1,tag:"equity",type:"trap",objective:"LO11.5",feedback:"Pareto efficiency means no further mutually beneficial trade remains. It does not guarantee that the final allocation is fair or equal."},
{id:250,q:"Steve and Austin move from an inefficient allocation to a point on the contract curve that is also closer to an equitable division. What does this movement illustrate?",options:["A movement toward both efficiency and equity","A movement away from Pareto efficiency","A pure production efficiency improvement","A monopoly pricing strategy"],a:0,tag:"equity",type:"graph-interpretation",objective:"LO11.5",feedback:"Moving to the contract curve improves efficiency, and moving toward a more balanced allocation can also improve equity."},
{id:251,q:"A monopolist faces demand P = 120 - 2Q and total cost TC = 30Q + Q^2. What is the monopolist’s profit-maximizing quantity?",options:["10","15","20","30"],a:1,tag:"power",type:"calculation",objective:"LO12.2",feedback:"Total revenue is 120Q - 2Q^2, so MR = 120 - 4Q. Marginal cost is 30 + 2Q. Set MR = MC: 120 - 4Q = 30 + 2Q, so Q = 15."},
{id:252,q:"Using demand P = 120 - 2Q, if the monopolist produces Q = 15, what price does it charge?",options:["60","75","90","105"],a:2,tag:"power",type:"calculation",objective:"LO12.2",feedback:"Plug Q = 15 into demand: P = 120 - 2(15) = 90."},
{id:253,q:"A monopoly graph shows constant marginal cost and a single-price monopolist. Which area represents the efficiency loss from monopoly?",options:["The deadweight loss triangle from units not produced","The entire profit rectangle","Consumer surplus above price","The fixed cost area"],a:0,tag:"power",type:"graph-interpretation",objective:"LO12.3",feedback:"With single-price monopoly, the efficiency loss is the deadweight loss from output being restricted below the efficient level where willingness to pay equals marginal cost."},
{id:254,q:"A monopolist is not perfectly price discriminating and produces where MR = MC. Why is the outcome inefficient?",options:["The monopolist produces where P = MC","The monopolist produces too little because price exceeds marginal cost","The monopolist earns zero profit","The monopolist has no fixed costs"],a:1,tag:"power",type:"trap",objective:"LO12.3",feedback:"Single-price monopoly restricts output. At the monopoly quantity, price is greater than marginal cost, meaning some mutually beneficial trades do not occur."},
{id:255,q:"Two consumers value two products differently. Consumer 1 values A at 50 and B at 20. Consumer 2 values A at 20 and B at 50. If marginal cost is 10 per product, why can bundling raise profit?",options:["Both consumers value the bundle at 70, allowing the firm to sell more total surplus","Bundling lowers marginal cost to zero","Bundling works only when consumers have identical values for each product","Bundling forces price to equal marginal cost"],a:0,tag:"power",type:"multi-step",objective:"LO12.4",feedback:"Each consumer values the bundle at 70 even though their values for the individual products differ. Bundling lets the firm capture more surplus than pricing each product separately."},
{id:256,q:"A firm sells a bundle for 70 to two consumers. Each bundle contains two products, and marginal cost is 10 per product. What is total profit from selling the bundle to both consumers?",options:["40","70","100","140"],a:2,tag:"power",type:"calculation",objective:"LO12.4",feedback:"Revenue is 70 × 2 = 140. Each bundle costs 20 to provide, so total cost is 40. Profit is 140 - 40 = 100."},
{id:257,q:"A natural monopoly is regulated using marginal-cost pricing. At the efficient quantity, price is below average cost. What must happen for the firm to remain in business?",options:["The firm must receive a subsidy covering the loss","The firm will earn monopoly profit","The firm must reduce output below the efficient quantity","The firm must become perfectly competitive"],a:0,tag:"power",type:"graph-interpretation",objective:"LO12.5",feedback:"Marginal-cost pricing can produce the efficient quantity, but if price is below average cost, the firm needs a subsidy to cover its losses."},
{id:258,q:"Under average-cost pricing for a natural monopoly, which statement is correct?",options:["Price equals average cost, so the firm earns zero economic profit","Price equals marginal cost, so the firm earns monopoly profit","Price is set below average cost, so the firm exits immediately","Output is always perfectly efficient"],a:0,tag:"power",type:"interpretation",objective:"LO12.5",feedback:"Average-cost pricing allows the firm to cover total cost, including normal profit. That means economic profit is zero, though output may be below the fully efficient quantity."},
{id:259,q:"Two differentiated Bertrand firms have symmetric best-response functions. Firm 1’s best response is P1 = 35 + 0.25P2, and Firm 2’s best response is P2 = 35 + 0.25P1. What is the symmetric equilibrium price?",options:["20.00","33.33","46.67","60.00"],a:2,tag:"strategy",type:"calculation",objective:"LO13.2",feedback:"In a symmetric equilibrium, P1 = P2 = P. Substitute into the best response: P = 35 + 0.25P. Therefore 0.75P = 35, so P = 46.67."},
{id:260,q:"Why does differentiated Bertrand competition usually lead to prices above marginal cost?",options:["Products are not perfect substitutes, so each firm retains some market power","Firms are legally required to collude","Consumers always buy from the lowest-price firm only","Marginal cost is always zero"],a:0,tag:"strategy",type:"interpretation",objective:"LO13.2",feedback:"When products are differentiated, a firm does not lose the entire market from charging a slightly higher price. That softens price competition and allows price to remain above marginal cost."},
{id:261,q:"In a Cournot market with inverse demand P = 100 - Q and constant MC = 20, two identical firms compete in quantities. What is each firm’s equilibrium output?",options:["20.00","26.67","40.00","60.00"],a:1,tag:"strategy",type:"calculation",objective:"LO13.1",feedback:"For two identical Cournot firms, each firm produces (a - c)/(n + 1). Here that is (100 - 20)/3 = 26.67."},
{id:262,q:"In the same Cournot market with P = 100 - Q and MC = 20, if each firm produces 26.67, what is approximately each firm’s profit?",options:["400.00","533.33","711.11","1200.00"],a:2,tag:"strategy",type:"calculation",objective:"LO13.1",feedback:"Total output is about 53.33, so price is about 46.67. Each firm’s margin is 46.67 - 20 = 26.67. Profit is 26.67 × 26.67 = about 711.11."},
{id:263,q:"In a Stackelberg market with P = 100 - Q and MC = 20, the leader produces 40 and the follower produces 20. What is total industry profit?",options:["400","800","1,000","1,200"],a:3,tag:"strategy",type:"calculation",objective:"LO13.3",feedback:"Total output is 60, so price is 40. The margin is 40 - 20 = 20. Leader profit is 20 × 40 = 800, and follower profit is 20 × 20 = 400. Total industry profit is 1,200."},
{id:264,q:"Why does the Stackelberg leader usually earn more than the follower?",options:["The leader commits to output first and anticipates the follower’s response","The follower chooses price first","The leader must produce the same output as the follower","The follower always has lower marginal cost"],a:0,tag:"strategy",type:"interpretation",objective:"LO13.3",feedback:"The leader gains a strategic advantage by committing to output first and choosing quantity while anticipating how the follower will respond."},
{id:265,q:"A monopolistically competitive firm is shown in long-run equilibrium. Which statement must be true?",options:["The firm earns positive economic profit","The firm earns no economic profit because demand is tangent to average total cost","The firm produces where price equals marginal cost","The firm has no market power"],a:1,tag:"power",type:"graph-interpretation",objective:"LO12.6",feedback:"In long-run monopolistic competition, entry shifts demand until it is tangent to average total cost. The firm still has market power, but economic profit is zero."},
{id:266,q:"Refer to the monopoly graph above. How does the monopolist determine the profit-maximizing output?",options:["Produce where demand intersects average total cost","Produce where marginal revenue equals marginal cost","Produce where price equals average total cost","Produce where demand equals marginal revenue"],a:1,tag:"power",type:"graph",objective:"LO12.2",image:"monopoly12.2.png",feedback:"A monopolist maximizes profit by producing the quantity where marginal revenue equals marginal cost. After finding that quantity, the monopolist uses the demand curve to determine the price."},
{id:267,q:"Refer to the monopoly graph above. After the monopolist chooses the profit-maximizing quantity, how is the monopoly price found?",options:["Move up from the chosen quantity to the demand curve","Move up from the chosen quantity to the marginal revenue curve","Use the minimum point of average total cost","Use the point where marginal cost crosses average total cost"],a:0,tag:"power",type:"graph",objective:"LO12.2",image:"monopoly12.2.png",feedback:"The monopolist chooses output where MR = MC, then moves up to the demand curve to find the highest price consumers are willing to pay for that quantity."},
{id:268,q:"Refer to the monopoly graph above. Which comparison determines whether the monopolist earns positive economic profit at the chosen output?",options:["Price compared with marginal revenue","Price compared with average total cost","Marginal revenue compared with average total cost","Marginal cost compared with demand"],a:1,tag:"power",type:"graph",objective:"LO12.2",image:"monopoly12.2.png",feedback:"Profit depends on price compared with average total cost at the chosen output. If price is above ATC, the monopolist earns positive economic profit. If price is below ATC, the monopolist earns a loss."},
{id:269,q:"Refer to the Edgeworth Box above. What does the purple curve running through the tangency points represent?",options:["The set of Pareto efficient allocations","The set of equal income allocations","The budget constraint for both individuals","The set of inefficient trades"],a:0,tag:"efficiency",type:"graph",objective:"LO11.4",image:"Edgeworth11.4.png",feedback:"The purple curve represents the contract curve. Points on the contract curve are Pareto efficient because the two individuals’ indifference curves are tangent, meaning no further mutually beneficial trade remains."},
{id:270,q:"Refer to the Edgeworth Box above. If an allocation is away from the contract curve, what does that imply?",options:["The allocation must be equitable","The allocation is Pareto efficient","There may still be mutually beneficial trades available","Both individuals have identical preferences"],a:2,tag:"efficiency",type:"graph",objective:"LO11.4",image:"Edgeworth11.4.png",feedback:"An allocation away from the contract curve is not Pareto efficient. Because the individuals’ indifference curves are not tangent there, it may be possible to reallocate goods in a way that makes at least one person better off without making the other worse off."},
{id:271,q:"Refer to the Edgeworth Box above. Which statement best connects efficiency and equity in this graph?",options:["Every point on the contract curve is automatically equitable","A point can be Pareto efficient even if it is not viewed as equitable","Equity requires staying away from the contract curve","Pareto efficiency means both people receive identical bundles"],a:1,tag:"equity",type:"graph",objective:"LO11.5",image:"Edgeworth11.4.png",feedback:"The contract curve shows Pareto efficient allocations, but efficiency does not guarantee fairness. A point can be efficient because no further mutually beneficial trades remain, while still being judged inequitable depending on how the goods are distributed."},
{id:272,q:"Refer to the Edgeworth Box above. What does the shaded area around point A represent?",options:["Allocations that may make at least one person better off without making the other worse off","Allocations that are less efficient than point A for both people","Allocations that require both people to receive identical bundles","Allocations where production costs are minimized"],a:0,tag:"efficiency",type:"graph",objective:"LO11.4",image:"edgeworth11.2.png",feedback:"The shaded lens shows allocations that may be Pareto improvements from point A. These are trades that can make at least one person better off without making the other person worse off."},
{id:273,q:"Refer to the Edgeworth Box above. If point A lies inside the shaded lens of possible trades, what does that imply about the starting allocation?",options:["It is already Pareto efficient","It is not Pareto efficient because mutually beneficial trades may still exist","It is automatically equitable","It maximizes total production"],a:1,tag:"efficiency",type:"graph",objective:"LO11.4",image:"edgeworth11.2.png",feedback:"Point A is not Pareto efficient if there are nearby allocations that both people would weakly prefer and at least one person would strictly prefer. The shaded area shows that mutually beneficial trades may still exist."},
{id:274,q:"Refer to the Edgeworth Box above. Why would voluntary trade tend to move away from point A?",options:["Because both individuals may be able to reach higher indifference curves","Because the contract curve always requires equal bundles","Because one person must lose for the other to gain","Because point A minimizes production cost"],a:0,tag:"efficiency",type:"graph",objective:"LO11.4",image:"edgeworth11.2.png",feedback:"Voluntary trade can move away from point A when both individuals can reach preferred allocations. The shaded lens identifies possible gains from trade, where at least one person is better off and neither person is worse off."},
{id:275,q:"Refer to the graph above. Assume point B is the autarky equilibrium and BC1 is the world price line after trade opens. Which point represents the production point after trade?",options:["A","B","C","None, because production does not change with trade"],a:0,tag:"interaction",type:"graph",objective:"LO11.4",image:"trade11.2.png",feedback:"With trade, the economy produces where the world price line is tangent to the production possibilities frontier. That occurs at point A."},
{id:276,q:"Refer to the graph above. Assume point B is the autarky equilibrium and BC1 is the world price line after trade opens. Which point represents the consumption point after trade?",options:["A","B","C","None, because consumption must equal production"],a:2,tag:"interaction",type:"graph",objective:"LO11.4",image:"trade11.2.png",feedback:"After trade opens, the economy can consume at a different point from where it produces. Point C is the consumption point because it lies on the trade line BC1 and reaches a higher indifference curve."},
{id:277,q:"Refer to the graph above. What is the main gain from opening to trade?",options:["The economy can move from IC1 to IC2 and reach a higher level of satisfaction","The economy must consume at the same point where it produces","The production possibilities frontier shifts outward immediately","The economy becomes productively inefficient"],a:0,tag:"efficiency",type:"graph",objective:"LO11.4",image:"trade11.2.png",feedback:"Trade allows the economy to specialize in production and then exchange along the world price line. This makes it possible to move from the lower indifference curve IC1 to the higher indifference curve IC2, showing gains from trade."},
{id:278,q:"Refer to the natural monopoly graph above. If the government requires marginal-cost pricing, which point shows the regulated price and quantity?",options:["E at Q1","F at Q2","H at Q3","G at Q3"],a:2,tag:"power",type:"graph",objective:"LO12.5",image:"monopoly12.5.png",feedback:"Marginal-cost pricing requires price to equal marginal cost. On the graph, marginal cost pricing occurs at point H, where the demand curve intersects marginal cost at Q3 and price P1."},
{id:279,q:"Refer to the natural monopoly graph above. Under marginal-cost pricing, why might the firm need a subsidy?",options:["Price is below average cost, so the firm cannot cover total cost","Price is above marginal cost, so the firm earns monopoly profit","Quantity is too low, so consumers refuse to buy","Demand is below marginal revenue, so production stops"],a:0,tag:"power",type:"graph",objective:"LO12.5",image:"monopoly12.5.png",feedback:"At the marginal-cost pricing quantity Q3, the regulated price is P1. Average cost is higher at point G, so the firm loses money per unit unless the government provides a subsidy."},
{id:280,q:"Refer to the natural monopoly graph above. If the government uses average-cost pricing instead, what outcome occurs?",options:["The firm charges P2 at Q3 and earns positive economic profit","The firm charges P3 at Q2 and earns zero economic profit","The firm charges P1 at Q3 and requires no subsidy","The firm charges P4 at Q1 and produces the monopoly quantity"],a:1,tag:"power",type:"graph",objective:"LO12.5",image:"monopoly12.5.png",feedback:"Average-cost pricing sets price equal to average cost. On the graph, that occurs at point F, with price P3 and quantity Q2. Because price equals average cost, the firm earns zero economic profit."},
{id:281,q:"Refer to the monopolistically competitive firm graph above. What quantity and price will the firm choose to maximize profit?",options:["Q1 and P1","Q1 and P4","Q2 and P3","Q3 and P2"],a:0,tag:"power",type:"graph",objective:"LO13.4",image:"moncomp13.4.png",feedback:"A monopolistically competitive firm maximizes profit where marginal revenue equals marginal cost. That occurs at point B, which gives output Q1. The firm then moves up to the demand curve to find the price, which is P1 at point A."},
{id:282,q:"Refer to the monopolistically competitive firm graph above. At the profit-maximizing output, what profit is the firm earning?",options:["A positive economic profit because price is above marginal cost","A loss because price is below average total cost","Zero economic profit because price equals average total cost","Maximum profit because marginal cost is minimized"],a:2,tag:"power",type:"graph",objective:"LO13.4",image:"moncomp13.4.png",feedback:"At the profit-maximizing output Q1, the firm charges price P1. Point A shows that price is equal to average total cost at that output, so the firm earns zero economic profit."},
{id:283,q:"Refer to the monopolistically competitive firm graph above. Which statement best describes the firm's long-run outcome?",options:["The firm is both allocatively and productively efficient","The firm is allocatively efficient because price equals marginal cost at Q1","The firm earns zero economic profit but produces less than the output that minimizes average total cost","The firm earns positive economic profit because demand is downward sloping"],a:2,tag:"power",type:"graph",objective:"LO13.4",image:"moncomp13.4.png",feedback:"In long-run monopolistic competition, firms earn zero economic profit, but they do not produce at minimum average total cost. Here the firm produces at Q1, while the minimum ATC occurs farther right, so the firm has excess capacity."}
],

elite:[
{id:7000,q:"Demand for electric vehicles rises, increasing demand for lithium. Lithium prices rise, battery supply falls, and laptop producers also face higher costs. What is the best interpretation?",options:["Only the electric vehicle market is affected","A demand shock creates general equilibrium spillovers through shared inputs","Laptop demand must have increased first","Battery producers are acting like monopolists"],a:1,tag:"interaction",type:"integration",objective:"LO11.1",feedback:"The key is the shared input. A shock in one market can move prices and output in related markets."},
{id:7001,q:"A drought reduces wheat supply. Bread prices rise, cereal producers face higher input costs, and some consumers switch toward rice. What does this chain show?",options:["Only supply shifts matter","One market disturbance can affect complements, substitutes, and input markets","Demand curves never shift after supply shocks","All prices must return to their original levels"],a:1,tag:"interaction",type:"multi-step",objective:"LO11.1",feedback:"This is a linked-market adjustment. Inputs, substitutes, and related goods all react."},
{id:7002,q:"A new tax raises the cost of producing gasoline. Consumers buy fewer large trucks, demand for truck tires falls, and rubber prices decline. Which market link is doing most of the work?",options:["Shared input demand only","Linked demand across related goods and input markets","Monopoly price discrimination","Public good free riding"],a:1,tag:"interaction",type:"trap",objective:"LO11.1",feedback:"Gasoline, trucks, tires, and rubber are linked through related demand and input demand. A shock in one market can ripple through the rest."},
{id:7003,q:"A boom in construction raises wages for carpenters. Furniture firms lose workers and cut output. What is the best general equilibrium explanation?",options:["Furniture demand must have fallen directly","Labor reallocation changes costs and supply in related markets","Wages cannot link different industries","Construction and furniture markets are unrelated"],a:1,tag:"interaction",type:"integration",objective:"LO11.1",feedback:"Labor is a shared resource. When one sector pulls workers away, other sectors face higher labor costs or reduced labor supply."},

{id:7004,q:"An economy is on its PPF, but the slope of the PPF differs from consumers’ marginal rate of substitution. What is true?",options:["The economy is both productively and allocatively efficient","The economy is productively efficient but not allocatively efficient","The economy is inside the PPF","The allocation must be equitable"],a:1,tag:"efficiency",type:"trap",objective:"LO11.2",feedback:"Being on the PPF only means productive efficiency. Allocative efficiency requires MRT = MRS."},
{id:7005,q:"At the current output, consumers are willing to pay $45 for the next unit, while marginal cost is $30. What should happen to move toward efficiency?",options:["Output should decrease because cost is positive","Output should increase because marginal benefit exceeds marginal cost","Output should stay fixed because price is above zero","Output should fall until profit is zero"],a:1,tag:"efficiency",type:"calculation",objective:"LO11.2",feedback:"If marginal benefit exceeds marginal cost, society gains from producing more."},
{id:7006,q:"Two consumers have different MRS values for the same two goods. What does that imply?",options:["The allocation is Pareto efficient","A mutually beneficial trade may still be possible","The allocation is necessarily fair","Production must be inefficient"],a:1,tag:"efficiency",type:"trap",objective:"LO11.4",feedback:"Different MRS values mean the consumers value trades differently, so gains from exchange may remain."},
{id:7007,q:"A competitive market produces where P = MC, but the outcome gives most resources to one person. Which statement is strongest?",options:["The outcome is inefficient because it is unequal","The outcome may be efficient but inequitable","The outcome must be both fair and efficient","The market failed because profits exist"],a:1,tag:"equity",type:"integration",objective:"LO11.5",feedback:"Efficiency and equity are not the same thing. An outcome can maximize surplus and still look unfair."},

{id:7008,q:"A factory’s private marginal cost is $20, and each unit creates $8 of external harm. If the market ignores the harm, what is the social marginal cost?",options:["$12","$20","$28","$160"],a:2,tag:"failure",type:"calculation",objective:"LO11.3",feedback:"Social marginal cost equals private marginal cost plus external damage: 20 + 8 = 28."},
{id:7009,q:"A good creates external benefits, but buyers only consider their private benefit. What is the likely market result?",options:["Too much output because social benefit exceeds private benefit","Too little output because buyers ignore benefits to others","Efficient output because buyers pay the price","No output because external benefits are illegal"],a:1,tag:"failure",type:"trap",objective:"LO11.3",feedback:"Positive externalities cause underproduction because the market ignores some benefits."},
{id:7010,q:"A market has many buyers and sellers, but sellers dump waste into a river without paying for the damage. What should we conclude?",options:["Competition guarantees efficiency","The market can still fail because external costs are ignored","The market is efficient if firms earn zero profit","Externalities only matter under monopoly"],a:1,tag:"failure",type:"integration",objective:"LO11.3",feedback:"Competition alone does not fix unpriced external costs. That’s the trap."},
{id:7011,q:"Consumers cannot tell high-quality used cars from low-quality used cars, so owners of high-quality cars leave the market. What problem is this?",options:["Public good underproduction","Adverse selection from asymmetric information","Natural monopoly regulation","Perfect price discrimination"],a:1,tag:"failure",type:"multi-step",objective:"LO11.3",feedback:"Bad information can drive good products out of the market. That is adverse selection."},

{id:7012,q:"A monopolist faces demand P = 120 - 2Q and MC = 40. MR = 120 - 4Q. What price does the monopolist charge?",options:["$40","$60","$80","$120"],a:2,tag:"power",type:"calculation",objective:"LO12.2",feedback:"Set MR = MC: 120 - 4Q = 40, so Q = 20. Then P = 120 - 2(20) = 80."},
{id:7013,q:"A monopolist produces where MR = MC, but charges a price above MC. Why is this inefficient?",options:["The monopolist earns profit","Some units valued above marginal cost are not produced","Average cost must be rising","The monopolist has no fixed costs"],a:1,tag:"power",type:"trap",objective:"LO12.3",feedback:"The deadweight loss comes from restricted output. Profit is not the main villain here."},
{id:7014,q:"A firm charges a low per-unit price equal to MC plus a fixed membership fee. What pricing strategy is this?",options:["Peak-load pricing","Two-part tariff","Average-cost regulation","Cournot competition"],a:1,tag:"power",type:"interpretation",objective:"LO12.4",feedback:"A two-part tariff combines a fixed fee with a per-unit price."},
{id:7015,q:"A natural monopoly has MC below ATC over the relevant range of output. If regulators require P = MC, what problem can occur?",options:["The firm may earn losses unless subsidized","The firm earns monopoly profit","Output must fall to zero immediately","Price discrimination becomes impossible"],a:0,tag:"power",type:"multi-step",objective:"LO12.5",feedback:"Marginal-cost pricing can create losses for a natural monopoly when MC is below ATC."},

{id:7016,q:"Two firms sell identical products and compete in prices. MC = $10. Both charge $16. What happens if one firm cuts price to $15.50?",options:["It loses the whole market","It can capture the market while still pricing above MC","It must earn zero profit","The rival is forced to raise price"],a:1,tag:"strategy",type:"trap",objective:"LO13.1",feedback:"In homogeneous Bertrand competition, undercutting above MC is profitable because the lower-price firm captures buyers."},
{id:7017,q:"In Cournot competition, Firm A increases output. Firm B reduces output, but not enough to fully offset Firm A. What happens to total output and price?",options:["Total output rises and price falls","Total output falls and price rises","Total output is unchanged and price is unchanged","Total output rises and price rises"],a:0,tag:"strategy",type:"multi-step",objective:"LO13.1",feedback:"Cournot quantities are strategic substitutes, but total output usually still rises when one firm expands."},
{id:7018,q:"Two firms sell differentiated products. Firm A raises price. Why might Firm B also raise price?",options:["Differentiation softens competition, so best responses can move upward","Bertrand firms must always cut price to MC","Capacity constraints disappear","Consumers always buy the cheaper product"],a:0,tag:"strategy",type:"integration",objective:"LO13.2",feedback:"Differentiation weakens direct substitution. A rival’s price increase can give the other firm room to raise price too."},
{id:7019,q:"In a Stackelberg model, why can the first mover earn more than the follower?",options:["The leader commits to output while anticipating the follower’s response","The follower chooses output first","Both firms must produce equal output","The leader always prices at MC"],a:0,tag:"strategy",type:"interpretation",objective:"LO13.3",feedback:"The leader moves first and chooses output strategically, knowing how the follower will react."},
{id:7020,q:"A monopolistically competitive firm is earning positive profit in the short run. What happens in the long run?",options:["Entry shifts demand facing the firm left until economic profit is driven toward zero","The firm becomes a natural monopoly","Price must fall to marginal cost exactly","The firm exits because profit is positive"],a:0,tag:"strategy",type:"multi-step",objective:"LO13.4",feedback:"Entry steals customers from existing firms, reducing demand for each firm until economic profit is pushed toward zero."},

{id:7021,q:"A policy redistributes income from high-income consumers to low-income consumers but reduces total surplus. What is this?",options:["A Pareto improvement","An efficiency-equity tradeoff","A public good problem","A monopoly pricing strategy"],a:1,tag:"equity",type:"interpretation",objective:"LO11.5",feedback:"Equity may improve while efficiency falls. That is the tradeoff."},
{id:7022,q:"An allocation is Pareto efficient but gives almost everything to one person. What is the correct conclusion?",options:["It must be socially optimal","It may be efficient but still fail society’s fairness goals","It is not Pareto efficient because it is unequal","It proves markets always fail"],a:1,tag:"equity",type:"trap",objective:"LO11.5",feedback:"Pareto efficiency does not mean fairness. That misconception needs to get stunned."},
{id:7023,q:"According to the Second Welfare Theorem, how can society pursue a fairer efficient outcome?",options:["Redistribute initial endowments, then allow competitive trade","Ban trade after redistribution","Force all consumers to hold equal bundles","Set every price equal to average cost"],a:0,tag:"equity",type:"integration",objective:"LO11.5",feedback:"The idea is to separate redistribution from the trading process: adjust endowments first, then let markets work."},

{id:7024,q:"Refer to the monopoly graph above. Which sequence correctly describes the monopolist’s decision process?",options:["Choose Q where demand equals MC, then set price from MR","Choose Q where MR = MC, then set price from the demand curve","Choose Q where ATC is minimized, then set price equal to MC","Choose the efficient quantity, then set price equal to ATC"],a:1,tag:"power",type:"graph-integration",objective:"LO12.2",image:"monopoly12.2.png",feedback:"A monopolist chooses output where MR = MC, then moves up to the demand curve to find the price consumers will pay for that quantity."},
{id:7025,q:"Refer to the monopoly graph above. If the monopolist is earning zero economic profit at the chosen output, what must be true?",options:["Price equals marginal cost","Price equals average total cost","Marginal revenue equals demand","Average total cost equals marginal revenue"],a:1,tag:"power",type:"graph-trap",objective:"LO12.2",image:"monopoly12.2.png",feedback:"Profit depends on price compared with average total cost. Zero economic profit occurs when price equals ATC at the chosen output."},
{id:7026,q:"Refer to the monopoly graph above. Why does the monopoly outcome create deadweight loss?",options:["The monopolist produces beyond the efficient quantity","The monopolist produces less than the quantity where willingness to pay equals marginal cost","The monopolist always earns negative profit","The monopolist charges a price equal to marginal cost"],a:1,tag:"power",type:"graph-integration",objective:"LO12.3",image:"monopoly12.2.png",feedback:"Deadweight loss occurs because the monopolist restricts output below the efficient level. Some units that consumers value more than they cost to produce are not sold."},

{id:7027,q:"Refer to the Edgeworth Box above. If the current allocation is not on the contract curve, what should happen through voluntary trade?",options:["Trade should stop because the allocation is already efficient","Trade may continue until a Pareto efficient allocation is reached","Both people must receive identical bundles","One person must become worse off for any trade to occur"],a:1,tag:"efficiency",type:"graph-integration",objective:"LO11.4",image:"Edgeworth11.4.png",feedback:"If the allocation is not on the contract curve, mutually beneficial trade may still exist. Voluntary trade tends to move toward a Pareto efficient allocation."},
{id:7028,q:"Refer to the Edgeworth Box above. Which statement best explains why the contract curve does not solve the equity problem?",options:["The contract curve only identifies Pareto efficient allocations, not whether those allocations are fair","The contract curve only shows inefficient allocations","Every point on the contract curve gives both people equal amounts","Equity is guaranteed whenever trade is voluntary"],a:0,tag:"equity",type:"graph-trap",objective:"LO11.5",image:"Edgeworth11.4.png",feedback:"The contract curve shows efficiency, not fairness. A point can be Pareto efficient while still giving one person much more than the other."},
{id:7029,q:"Refer to the shaded Edgeworth Box above. What does the shaded lens around point A show?",options:["Allocations that are impossible after trade","Allocations that may be Pareto improvements from the starting point","Allocations that are less preferred by both people","Allocations where both people receive identical bundles"],a:1,tag:"efficiency",type:"graph",objective:"LO11.4",image:"edgeworth11.2.png",feedback:"The shaded lens shows possible gains from trade. These allocations can make at least one person better off without making the other worse off."},
{id:7030,q:"Refer to the trade graph above. Why can the economy consume at point C even though it produces at point A?",options:["Trade allows production and consumption to differ","The PPF shifts outward immediately","Point C is inside the PPF","The economy ignores opportunity cost"],a:0,tag:"interaction",type:"graph-integration",objective:"LO11.4",image:"trade11.2.png",feedback:"With trade, an economy can specialize in production and then exchange along the world price line. That allows consumption at a point different from production."},
{id:7031,q:"Refer to the trade graph above. What is the strongest evidence that trade improves welfare?",options:["The economy moves from IC1 to IC2","The economy produces fewer movies","The economy consumes fewer tacos","The budget constraint disappears"],a:0,tag:"efficiency",type:"graph",objective:"LO11.4",image:"trade11.2.png",feedback:"The move from IC1 to IC2 shows that trade allows the economy to reach a higher level of satisfaction."},

{id:7032,q:"Refer to the natural monopoly graph above. Which policy produces the efficient quantity but may require a subsidy?",options:["Unregulated monopoly pricing","Marginal-cost pricing","Average-cost pricing","Perfect price discrimination"],a:1,tag:"power",type:"graph-integration",objective:"LO12.5",image:"monopoly12.5.png",feedback:"Marginal-cost pricing sets price equal to marginal cost and produces the efficient quantity. But if price is below average cost, the firm needs a subsidy to avoid losses."},
{id:7033,q:"Refer to the natural monopoly graph above. Why is average-cost pricing often used instead of marginal-cost pricing?",options:["It lets the firm cover total cost without requiring a subsidy","It produces the fully efficient quantity","It gives the firm monopoly profit","It sets price equal to marginal revenue"],a:0,tag:"power",type:"graph-trap",objective:"LO12.5",image:"monopoly12.5.png",feedback:"Average-cost pricing allows the firm to break even because price equals average cost. The tradeoff is that output is usually below the fully efficient marginal-cost-pricing quantity."},

{id:7034,q:"Refer to the monopolistically competitive firm graph above. Why is the firm earning zero economic profit even though it has market power?",options:["Demand is tangent to average total cost at the profit-maximizing quantity","Price equals marginal cost","The firm produces at minimum average total cost","Marginal revenue equals demand"],a:0,tag:"strategy",type:"graph-integration",objective:"LO13.4",image:"moncomp13.4.png",feedback:"In long-run monopolistic competition, entry shifts each firm’s demand curve until it is tangent to ATC. The firm still has market power, but economic profit is zero."},
{id:7035,q:"Refer to the monopolistically competitive firm graph above. What inefficiency remains in the long run?",options:["The firm produces too much output","The firm produces where price equals marginal cost","The firm produces less than the output that minimizes average total cost","The firm earns permanent positive profit"],a:2,tag:"strategy",type:"graph-trap",objective:"LO13.4",image:"moncomp13.4.png",feedback:"Monopolistically competitive firms produce less than the output that minimizes ATC. This is excess capacity."}
]

};

