national-engine.areaFunction:
function getAreaName(r) {
    if (r <= 9) return "The Web of Equilibrium";
    if (r === 10) return "The Architect’s Domain";
    if (r <= 19) return "The Monopoly Throne";
    if (r === 20) return "The Seat of the Price Maker";
    if (r <= 25) return "The Strategic Corridor";
    if (r <= 29) return "The War of Responses";
    return "The Throne of Dominion";
}

