mint-ash-gold.resourceSource:
let latestReviewMaterialsHTML = "";
function getRecommendedReviewResources(report){
    const catalog = window.INSTRUCTIONAL_RESOURCES;
    if(!catalog || !Array.isArray(catalog.resources)) return [];

    const resourceById = new Map(catalog.resources.map(resource => [resource.id, resource]));
    const selectedIds = [];
    const addIds = ids => (ids || []).forEach(id => {
        if(resourceById.has(id) && !selectedIds.includes(id)) selectedIds.push(id);
    });
    const objectiveIds = (report && report.weakestObjectives || [])
        .map(entry => String(entry && entry.key || "").match(/LO\d+\.\d+/i))
        .filter(Boolean)
        .map(match => match[0].toUpperCase());

    objectiveIds.forEach(objectiveId => {
        const mapping = catalog.objectiveMappings && catalog.objectiveMappings[objectiveId];
        if(mapping){
            addIds(mapping.resourceIds);
            addIds(mapping.fallbackResourceIds);
        }
    });

    if(!selectedIds.length){
        Object.values(catalog.fallbackResourceIds || {}).forEach(addIds);
    }

    return selectedIds
        .map(id => resourceById.get(id))
        .filter(Boolean)
        .slice(0, Number(catalog.settings && catalog.settings.maximumRecommendations) || 3);
}
function renderRecommendedReview(report){
    const resources = report.recommendations || getRecommendedReviewResources(report);
    if(!resources.length){
        return '<div class="mastery-section"><h3>Recommended Review</h3><p class="mastery-empty">No student-facing review materials are mapped for this run yet.</p></div>';
    }

    return '<div class="mastery-section" id="recommendedReviewSection">'
        + '<h3>Recommended Review</h3>'
        + '<p class="mastery-row-meta">These materials are matched to the learning-objective signals above.</p>'
        + resources.map(resource => '<article class="mastery-row" style="display:block;margin:10px 0;padding:14px;">'
            + '<div class="mastery-row-main"><span class="mastery-row-name">' + escapeHTML(resource.title) + '</span>'
            + '<span class="mastery-row-score" style="font-size:.78em">' + escapeHTML(resource.typeLabel || resource.type) + '</span></div>'
            + '<span class="mastery-row-meta">' + escapeHTML(resource.description) + '</span><br>'
            + '<a class="continue-btn" style="display:inline-block;margin-top:10px;text-decoration:none;" href="' + escapeHTML(resource.url) + '" target="_blank" rel="noopener noreferrer">' + escapeHTML(resource.actionLabel || 'Open Resource') + '</a>'
            + '</article>').join('')
        + '<button class="continue-btn secondary-modal-btn" onclick="showReviewMaterialsScreen()">Review Materials</button>'
        + '</div>';
}
function showReviewMaterialsScreen(){
    const gameBox = document.getElementById("gameBox");
    if(!gameBox) return;
    latestReviewMaterialsHTML = gameBox.innerHTML;
    const report = getMasteryReportData();
    const resources = report.recommendations || getRecommendedReviewResources(report);
    const cards = resources.length ? resources.map(resource => '<article class="mastery-section" style="margin:12px 0;">'
        + '<h3>' + escapeHTML(resource.title) + '</h3>'
        + '<p class="mastery-row-meta">' + escapeHTML(resource.typeLabel || resource.type) + ' · ' + escapeHTML(resource.description) + '</p>'
        + '<a class="continue-btn" style="display:inline-block;text-decoration:none;" href="' + escapeHTML(resource.url) + '" target="_blank" rel="noopener noreferrer">' + escapeHTML(resource.actionLabel || 'Open Resource') + '</a>'
        + '</article>').join('') : '<p class="mastery-empty">No mapped student-facing materials are available for this report.</p>';
    gameBox.innerHTML = '<div id="reviewMaterialsScreen" class="mastery-report-screen">'
        + '<h1 class="mastery-report-title">REVIEW MATERIALS</h1>'
        + '<p class="mastery-report-subtitle">Focused materials selected from this game\'s local course catalog.</p>'
        + cards
        + '<div class="mastery-actions"><button class="continue-btn secondary-modal-btn" onclick="restoreMasteryReportFromMaterials()">Back to Mastery Report</button></div>'
        + '</div>';
}
function restoreMasteryReportFromMaterials(){
    const gameBox = document.getElementById("gameBox");
    if(gameBox && latestReviewMaterialsHTML) gameBox.innerHTML = latestReviewMaterialsHTML;
}
function renderInstructionalResourceSection(report){return renderRecommendedReview(report);}

