      sfxBossHit.volume = 0.5;
const sfxCorrect = new Audio('ding.wav');
      sfxCorrect.volume = 0.25;
const sfxWrong = new Audio('mistake.wav');
      sfxWrong.volume = 0.4;

[sfxMilestone, sfxCorrect, sfxWrong].forEach(audio => {
  audio.preload = 'auto';
});

const hallwayImages = [
    "hallway1.webp",
    "hallway2.webp",
    "hallway3.webp"
];

let soundEnabled = true;
const SOUND_PREF_KEY = "exchangeCitadelSoundEnabled";

function updateSoundToggle(){
  const button = document.getElementById("soundToggle");
  if(!button) return;
  button.innerText = soundEnabled ? "Sound On" : "Sound Off";
}

function setAllGameAudioMuted(isMuted){
  [bgMusic, bossMusic, finalBossMusic, sfxMilestone, sfxVictory, sfxBossHit, sfxCorrect, sfxWrong]
    .filter(Boolean)
    .forEach(audio => {
      audio.muted = isMuted;
    });
}

function toggleGameSound(){
  soundEnabled = !soundEnabled;

  localStorage.setItem(SOUND_PREF_KEY, soundEnabled ? "true" : "false");
  setAllGameAudioMuted(!soundEnabled);
  updateSoundToggle();

  if(soundEnabled){
      unlockGameSfx();
      resumeCurrentMusic();
  } else {
      pauseAllGameMusic();
  }
}

function restoreSoundSetting(){
  const saved = localStorage.getItem(SOUND_PREF_KEY);

  soundEnabled = saved !== "false";

  setAllGameAudioMuted(!soundEnabled);
  updateSoundToggle();
}

restoreSoundSetting();

// Mobile browsers require sound effects to be authorized by a direct user gesture.
// Prime only the three known SFX files; optional absent sounds remain silent fallbacks.
let gameSfxUnlocked = false;

function unlockGameSfx(){
  if(gameSfxUnlocked || !soundEnabled) return;

  gameSfxUnlocked = true;

  [sfxMilestone, sfxCorrect, sfxWrong].forEach(audio => {
    if(!audio || typeof audio.play !== "function") return;

    const originalVolume = audio.volume;
    const originalMuted = audio.muted;

    try {
      audio.muted = false;
      audio.volume = 0;
      audio.currentTime = 0;

      const playAttempt = audio.play();
      if(playAttempt && typeof playAttempt.then === "function"){
        playAttempt.then(() => {
          audio.pause();
          audio.currentTime = 0;
          audio.volume = originalVolume;
          audio.muted = !soundEnabled || originalMuted;
        }).catch(error => {
          audio.volume = originalVolume;
          audio.muted = !soundEnabled || originalMuted;
          gameSfxUnlocked = false;
          console.warn("SFX unlock blocked:", audio.src, error);
        });
      } else {
        audio.pause();
        audio.currentTime = 0;
        audio.volume = originalVolume;
        audio.muted = !soundEnabled || originalMuted;
      }
    } catch(error) {
      audio.volume = originalVolume;
      audio.muted = !soundEnabled || originalMuted;
      gameSfxUnlocked = false;
      console.warn("SFX unlock blocked:", audio.src, error);
    }
  });
}

document.addEventListener("pointerdown", unlockGameSfx, { capture: true });
document.addEventListener("keydown", unlockGameSfx, { capture: true });



// =============================================
// QUESTION GRAPH LIGHTBOX
// Click any question graph to enlarge it. Click the X, backdrop, or Escape to close.
// =============================================
function openGraphLightbox(src, altText){
    const lightbox = document.getElementById("graphLightbox");
    const lightboxImg = document.getElementById("graphLightboxImg");
    if(!lightbox || !lightboxImg || !src) return;

    lightboxImg.src = src;
    lightboxImg.alt = altText || "Expanded question graph";
    lightbox.classList.add("active");
    lightbox.setAttribute("aria-hidden", "false");
}

function closeGraphLightbox(){
    const lightbox = document.getElementById("graphLightbox");
    const lightboxImg = document.getElementById("graphLightboxImg");
    if(!lightbox) return;

    lightbox.classList.remove("active");
    lightbox.setAttribute("aria-hidden", "true");
    if(lightboxImg) lightboxImg.removeAttribute("src");
}

document.addEventListener("click", function(event){
    const graphImg = event.target.closest("#questionImageBox img");
    if(graphImg){
        openGraphLightbox(graphImg.src, graphImg.alt);
        return;
    }

    if(event.target.id === "graphLightbox" || event.target.id === "graphLightboxClose"){
        closeGraphLightbox();
    }
});

document.addEventListener("keydown", function(event){
    if(event.key === "Escape"){
        closeGraphLightbox();
    }
});

function setGameControlsVisible(isVisible){
    document.body.classList.toggle("game-active", !!isVisible);
}

setGameControlsVisible(false);

function pauseAllGameMusic(){
    [bgMusic, bossMusic, finalBossMusic].filter(Boolean).forEach(audio => {
        audio.pause();
    });
}

function safePlay(audio){
    if(!audio || !soundEnabled) return Promise.resolve();

    audio.muted = false;

    return audio.play().catch(error => {
        console.warn("Audio play blocked:", error);
    });
}

function safePlaySfx(audio){
    if(!audio || !soundEnabled) return Promise.resolve();

    try {
        audio.pause();
        audio.currentTime = 0;
    } catch(error) {
        console.warn("SFX reset failed:", audio?.src || "unknown", error);
    }

    return safePlay(audio);
}


function resumeCurrentMusic(){
    if(typeof currentMusic !== "undefined"){
        if(currentMusic === "boss") return safePlay(bossMusic);
        if(currentMusic === "finalBoss") return safePlay(finalBossMusic);
        if(currentMusic === "exploration") return safePlay(bgMusic);
    }

    return safePlay(bgMusic);
}

